diff --git a/lib/wiki/applyEditSet.ts b/lib/wiki/applyEditSet.ts
index c17cd08..d8b8f20 100644
--- a/lib/wiki/applyEditSet.ts
+++ b/lib/wiki/applyEditSet.ts
@@ -25,6 +25,18 @@ export interface EditSet {
   usage?: { model?: string; inputTokens?: number; outputTokens?: number };
 }

+// ★왜 검토가 필요한지★ 한 줄 사유(순수·공유) — 검토 list·이전 검토·상세 GET이 같은 로직을 쓴다.
+//   ① 모순이면 빈 문자열(모순 배너가 따로 설명) ② 분석 모델 자기보고(review_reason) ③ 저신뢰 ④ 그 외 needs_human.
+//   ★이전(처리된) 항목도 editSet이 보존돼 동일하게 계산됨★ — review_reason 없는 옛 데이터는 폴백 문구로 뜬다.
+export function computeReviewReason(es: EditSet, confidence: number | null | undefined, threshold: number): string {
+  if (Array.isArray(es.contradictions) && es.contradictions.length) return "";
+  const llm = typeof es.review_reason === "string" ? es.review_reason.trim() : "";
+  if (llm) return llm;
+  const conf = confidence ?? 1;
+  if (conf < threshold) return `분석 신뢰도가 낮아요 (${Math.round(conf * 100)}%) — 내용이 맞는지 확인해 주세요.`;
+  return "분석 모델이 사람 확인을 요청했어요 (예: 표·목록이 많아 일부 누락 가능). 빠진 내용이 없는지 확인해 주세요.";
+}
+
 // 편집셋이 ★위키에 반영할 실제 페이지 편집★을 담고 있는지(순수). 빈 edits(또는 내용 없는 op)면 적용해도
 //   페이지가 안 생긴다 → "반영됨/페이지로 가기"로 표시하면 끊긴 링크(404)다. ★정직한 실패★ 판단에 쓴다.
 export function hasContentEdits(editSet: { edits?: WikiEdit[] } | null | undefined): boolean {
diff --git a/lib/wiki/repo.ts b/lib/wiki/repo.ts
index aadd00b..ad49a5f 100644
--- a/lib/wiki/repo.ts
+++ b/lib/wiki/repo.ts
@@ -75,6 +75,24 @@ export async function commitAll(
   return res.commit;
 }

+/**
+ * 한 커밋을 ★역적용(revert)★해 작업트리에만 반영한다(커밋은 호출부가 commitAll로 — 이력 보존·trailer 일관).
+ *   검토 승인 '되돌리기'(applied 취소)용. 반환=그 커밋이 건드린 파일 경로(색인 동기용).
+ *   ★충돌(이후 변경이 같은 파일을 만짐)이면 abort 후 throw★ — 작업트리 안전. withWikiWriteLock 안에서 호출.
+ */
+export async function revertCommitNoCommit(sha: string): Promise<string[]> {
+  const g = git();
+  const files = (await g.raw(["show", "--name-only", "--format=", sha]))
+    .split("\n").map((s) => s.trim()).filter(Boolean);
+  try {
+    await g.raw(["revert", "--no-commit", sha]);
+  } catch {
+    try { await g.raw(["revert", "--abort"]); } catch { /* 이미 정리됨 */ }
+    throw new Error("이후 변경과 충돌해 자동 되돌리기를 못 했습니다. 해당 페이지를 수동으로 확인·정리하세요.");
+  }
+  return files;
+}
+
 // ── 수정 이력(git 기반) ────────────────────────────────────────────
 // 위키는 git 저장소 + 모든 인제스트 커밋에 provenance trailer(Source-Sha256/Model/Gate…)가 있어,
 //   페이지별 git log = '언제·어떤 자료 업로드·어떤 모델로 바뀌었는지', git show = '무엇이 바뀌었는지(diff)'.

