1	import { NextResponse } from "next/server";
2	import { getSessionUser } from "@/lib/auth/session";
3	import { allowedScopes, scopeWikiPrefix, canManageScope } from "@/lib/acl/scope";
4	import { prisma } from "@/lib/db";
5	import { getStaleDays, getIngestReviewThreshold } from "@/lib/settings";
6	import { flaggedPagesFromDownvotes } from "@/lib/wiki/feedbackFlags";
7	import { computeReviewReason } from "@/lib/wiki/applyEditSet";
8	import { scopeIdFromTeamScope } from "@/lib/jobs/stale";
9	import { reapStuckApplying } from "@/lib/ingest";
10	
11	// 검토 큐 — 인제스트가 needs_human(모순/대체)으로 보류한 항목 목록. docs/12.
12	export const runtime = "nodejs";
13	
14	export async function GET() {
15	  const user = await getSessionUser();
16	  if (!user) return NextResponse.json({ error: "로그인이 필요합니다." }, { status: 401 });
17	
18	  // scope id(common·project-<slug>·personal/<id>) → ★한글 표시명★. 룸은 이름 조회(메모이즈).
19	  const nameCache = new Map<string, string>();
20	  async function scopeName(scope: string): Promise<string> {
21	    if (nameCache.has(scope)) return nameCache.get(scope)!;
22	    let name = scope;
23	    if (scope === "common") name = "회사 공통";
24	    else if (scope.startsWith("personal/")) name = "개인 위키";
25	    else if (scope.startsWith("project-")) {
26	      const p = await prisma.project.findUnique({ where: { slug: scope.slice("project-".length) }, select: { name: true } });
27	      name = p?.name ?? scope;
28	    }
29	    nameCache.set(scope, name);
30	    return name;
31	  }
32	
33	  const allowed = [...new Set((await allowedScopes(user)).map((s) => scopeWikiPrefix(s.id)))];
34	  // ★멈춘 APPLYING 회수★(BUG-TRIAGE #9) — 하드 크래시로 박제된 검토건을 다시 목록에 띄운다(자가치유·멱등).
35	  await reapStuckApplying(allowed).catch(() => {});
36	  const jobs = await prisma.ingestJob.findMany({
37	    where: { status: "NEEDS_REVIEW", teamScope: { in: allowed } },
38	    include: { source: { select: { id: true, title: true, type: true } } },
39	    orderBy: { id: "desc" },
40	    take: 50,
41	  });
42	
43	  const threshold = await getIngestReviewThreshold(); // 저신뢰 판정 기준(사유 문구용)
44	  const items = await Promise.all(jobs.map(async (j) => {
45	    let summary = "";
46	    let edits: { op: string; path: string }[] = [];
47	    let contradictions: { subject: string; existing: string; incoming: string; page?: string; existingDate?: string }[] = [];
48	    let reviewReason = "";
49	    try {
50	      const es = JSON.parse(j.editSet || "{}");
51	      summary = es.log_entry || "";
52	      edits = (es.edits || []).map((e: { op: string; path: string }) => ({ op: e.op, path: e.path }));
53	      if (Array.isArray(es.contradictions)) contradictions = es.contradictions;
54	      reviewReason = computeReviewReason(es, j.confidence, threshold); // ★왜 검토인지★(공유 헬퍼)
55	    } catch { /* 파싱 실패 무시 */ }
56	    // ★최근성(언제 자료인지)★ — 충돌하는 기존 페이지의 마지막 갱신 시각을 붙여, reviewer가 '최신=새 자료'를 한눈에 판단.
57	    const cPaths = contradictions.map((c) => c.page).filter((p): p is string => !!p);
58	    if (cPaths.length) {
59	      const docs = await prisma.wikiDoc.findMany({ where: { path: { in: cPaths } }, select: { path: true, updatedAt: true } });
60	      const dateByPath = new Map(docs.map((d) => [d.path, d.updatedAt.toISOString()]));
61	      contradictions = contradictions.map((c) => (c.page && dateByPath.has(c.page) ? { ...c, existingDate: dateByPath.get(c.page) } : c));
62	    }
63	    return {
64	      jobId: j.id,
65	      scope: j.teamScope,
66	      scopeName: await scopeName(j.teamScope), // 한글 룸 이름
67	      sourceId: j.source.id,
68	      sourceTitle: j.source.title,
69	      sourceType: j.source.type,
70	      confidence: j.confidence,
71	      createdAt: j.createdAt.toISOString(),
72	      summary,
73	      edits,
74	      reviewReason, // ★왜 검토인지★ 한 줄 사유(모순이면 빈 문자열 — 아래 contradictions 배너가 설명).
75	      contradictions, // ★모순 검증 게이트(B)★ — 왜 검토인지(기존↔새 자료 충돌). 없으면 빈 배열.
76	    };
77	  }));
78	
79	  // ★이전(처리된) 검토 목록★ — 사람이 검토해 승인(gate=HUMAN_REVIEW)했거나 반려(REJECTED)한 최근 항목.
80	  //   하단에 구별 표시(무엇을 어떻게 결정했는지 되짚기용). 자동적용(AUTO_APPLIED)은 검토를 거친 게 아니라 제외.
81	  const pastJobs = await prisma.ingestJob.findMany({
82	    where: { teamScope: { in: allowed }, OR: [{ status: "APPLIED", gate: "HUMAN_REVIEW" }, { status: "REJECTED" }] },
83	    include: { source: { select: { title: true, type: true } } },
84	    orderBy: { updatedAt: "desc" },
85	    take: 20,
86	  });
87	  const past = await Promise.all(pastJobs.map(async (j) => {
88	    let summary = "";
89	    let reviewReason = "";
90	    let hasContradiction = false;
91	    try {
92	      const es = JSON.parse(j.editSet || "{}");
93	      summary = es.log_entry || "";
94	      hasContradiction = Array.isArray(es.contradictions) && es.contradictions.length > 0;
95	      reviewReason = computeReviewReason(es, j.confidence, threshold); // ★이전 항목도 사유 표시★(보존된 editSet)
96	    } catch { /* 무시 */ }
97	    return {
98	      jobId: j.id, scope: j.teamScope, scopeName: await scopeName(j.teamScope),
99	      sourceTitle: j.source.title, sourceType: j.source.type,
100	      decision: j.status === "APPLIED" ? "approved" : "rejected",
101	      decidedAt: j.updatedAt.toISOString(), summary, reviewReason, hasContradiction,
102	      canReDecide: await canManageScope(user, j.teamScope), // 재결정(승인/되돌리기) 권한
103	    };
104	  }));
105	
106	  // 승격 요청 — ★대상 범위(toScope)를 관리할 수 있는 사람★에게 노출(부모 룸 OWNER·공통은 ADMIN).
107	  const allPending = await prisma.promotion.findMany({ where: { status: "PENDING" }, orderBy: { id: "desc" }, take: 50 });
108	  const promotions: { id: number; fromScope: string; toScope: string; fromName: string; toName: string; path: string; title: string; createdAt: string }[] = [];
109	  for (const p of allPending) {
110	    if (await canManageScope(user, p.toScope)) {
111	      promotions.push({ id: p.id, fromScope: p.fromScope, toScope: p.toScope, fromName: await scopeName(p.fromScope), toName: await scopeName(p.toScope), path: p.path, title: p.title, createdAt: p.createdAt.toISOString() });
112	    }
113	  }
114	
115	  // ★관리 권한 scope★(오래됨·👎 환류 공통) — 한 번만 계산해 둘이 재사용.
116	  const manageable: string[] = [];
117	  for (const s of allowed) if (await canManageScope(user, s)) manageable.push(s);
118	  const inManageable = (p: string) => manageable.some((s) => p === s || p.startsWith(s + "/"));
119	
120	  // 스테일(오래된) 페이지 — 관리 권한 scope에서 임계일보다 오래 갱신 안 된 지식 페이지. 검토·갱신 권장.
121	  const staleDays = await getStaleDays();
122	  const stalePages: { path: string; scope: string; scopeName: string; title: string; ageDays: number; link: string }[] = [];
123	  if (staleDays > 0 && manageable.length) {
124	    const cutoff = new Date(Date.now() - staleDays * 86400 * 1000);
125	    const docs = await prisma.wikiDoc.findMany({
126	      where: { scope: { in: manageable }, updatedAt: { lt: cutoff }, category: { in: ["entities", "concepts", "topics"] } },
127	      orderBy: { updatedAt: "asc" }, take: 80,
128	      select: { path: true, scope: true, title: true, updatedAt: true },
129	    });
130	    // ★'열면 자동 갱신'(WikiReview) 반영★ — 최근 열람/검토된 페이지는 제외(stale 잡과 동일 기준).
131	    const reviews = docs.length ? await prisma.wikiReview.findMany({ where: { path: { in: docs.map((d) => d.path) } }, select: { path: true, reviewedAt: true } }) : [];
132	    const reviewedAt = new Map(reviews.map((r) => [r.path, r.reviewedAt]));
133	    for (const d of docs) {
134	      const rv = reviewedAt.get(d.path);
135	      if (rv && rv >= cutoff) continue; // 최근 열람/검토됨 → 방치 아님
136	      const fresh = rv && rv > d.updatedAt ? rv : d.updatedAt;
137	      stalePages.push({
138	        path: d.path, scope: d.scope, scopeName: await scopeName(d.scope), title: d.title,
139	        ageDays: Math.floor((Date.now() - fresh.getTime()) / 86400000),
140	        link: `/?room=${encodeURIComponent(scopeIdFromTeamScope(d.scope))}&page=${encodeURIComponent(d.path)}`,
141	      });
142	      if (stalePages.length >= 30) break;
143	    }
144	  }
145	
146	  // ★👎 많이 받은 페이지(A-3)★ — 관리 권한 scope의 부정평가를 인용 페이지별로 모아 '검토 1순위'로.
147	  //   ACL 이중 가드: 피드백 scope ∈ 관리가능 + 페이지 경로 ∈ 관리가능(cross-scope 인용된 타 scope 페이지 제외).
