135	      return NextResponse.json({ error: "편집셋 파싱 실패" }, { status: 500 });
136	    }
137	    // ★정직한 실패★: 적용할 페이지 편집이 없는 검토건(모델이 자료에서 추출한 내용 없음 — 스캔 PDF 미독해 등)을
138	    //   승인하면 페이지가 안 생기는데 "반영됨+페이지로 가기"가 떠 끊긴 링크(404)가 된다. 가짜 성공 대신 실패로 명확히.
139	    if (!hasContentEdits(editSet)) {
140	      await prisma.ingestJob.update({
141	        where: { id: jobId },
142	        data: { status: "FAILED", error: "분석 결과 위키에 반영할 편집이 없습니다(자료를 읽지 못했거나 새 정보 없음). 다른 모델(Gemini 등)로 다시 분석하세요." },
143	      }).catch(() => {});
144	      return NextResponse.json({ error: "적용할 위키 편집이 없습니다 — 자료를 읽지 못한 분석입니다. 다른 모델(Gemini 등)로 다시 분석하세요.", status: "FAILED" }, { status: 422 });
145	    }
146	    try {
147	      await assertWikiReady();
148	      const { commitSha, changed, archived } = await withWikiWriteLock(async () => {
149	        // 갱신 전 각 대상 페이지의 기존 sha 수집(op:create가 옛 sha를 덮어써도 보강 — 자동적용과 동일).
150	        const preShaByPath = new Map<string, string[]>();
151	        for (const e of editSet.edits ?? []) {
152	          const rel = coercePath(job.teamScope, e.path);
153	          if (preShaByPath.has(rel)) continue;
154	          try { preShaByPath.set(rel, extractShas(await fs.readFile(wikiAbsPath(rel), "utf8"))); } catch { /* 새 페이지 */ }
155	        }
156	        const changed = await applyEditSet(job.teamScope, editSet);
157	        // ★원본 sha 출처 보장★ — 자동적용 경로(ingestText)와 동일하게, 적용된 지식 페이지마다 (기존 sha ∪ 원본 sha)를
158	        //   '## 출처'에 보강한다. 없으면 pages(sha 검색)가 빈값 → '위키 페이지를 찾지 못했습니다'(자료↔위키 이동 끊김).
159	        for (const rel of changed) {
160	          if (!/\/(entities|concepts|topics)\/[^/]+\.md$/.test(rel)) continue;
161	          const required = [...new Set([...(preShaByPath.get(rel) ?? []), job.source.sha256])];
162	          await ensureSourcesSection(wikiAbsPath(rel), required);
163	        }
164	        // ★분석 푸터(🤖 분석 모델·토큰·시각)★ — 자동적용과 동일하게 승인 페이지에도 단다. 토큰은 분석 시
165	        //   editSet.usage에 저장됨(없는 옛 잡은 0). 누락 시 승인 지식만 출처 메타가 비던 버그 수정.
166	        const u = editSet.usage;
167	        await stampAnalysisCost(changed, u?.model || job.model || "(모델 미상)", u?.inputTokens ?? 0, u?.outputTokens ?? 0);
168	        // ★모순 '새 정보로 대체'★ — 충돌하던 기존 페이지를 .archive로 옮겨 위키엔 최신 하나만 남긴다(되돌리기 가능).
169	        //   방금 적용된 페이지(changed)는 그게 새 정보이므로 보존. 모순 아닌 일반 검토건은 contradictions 비어 no-op.
