if (action === "reject") {
  // ★이미 승인·적용된 것 되돌리기(un-approve)★ — 그 적용 커밋을 git revert(이력 보존)로 원복 + REJECTED.
  if (isApprovedHuman) {
    if (!job.commitSha) return NextResponse.json({ error: "되돌릴 커밋 정보가 없어 자동 되돌리기를 못 합니다(페이지를 수동 정리하세요)." }, { status: 422 });
    const claim = await prisma.ingestJob.updateMany({ where: { id: jobId, status: "APPLIED" }, data: { status: "APPLYING" } });
    if (claim.count !== 1) return NextResponse.json({ error: "이미 처리 중이거나 상태가 바뀐 항목입니다." }, { status: 409 });
    try {
      await assertWikiReady();
      const changed = await withWikiWriteLock(async () => {
        const files = await revertCommitNoCommit(job.commitSha!); // 충돌이면 throw(아래 롤백)
        await commitAll(`review-undo(${job.teamScope}): ${job.source.title} [승인 되돌리기]`, { team: job.teamScope, gate: "REVERTED", model: "(되돌리기)" });
        return files;
      });
      await prisma.ingestJob.update({ where: { id: jobId }, data: { status: "REJECTED", resultPages: 0 } });
      void syncWikiDocs(changed).catch(() => {});
      return NextResponse.json({ ok: true, status: "REJECTED", reverted: true });
    } catch (err) {
      await prisma.ingestJob.update({ where: { id: jobId }, data: { status: "APPLIED" } }).catch(() => {}); // 클레임 롤백
      return NextResponse.json({ error: String(err instanceof Error ? err.message : err) }, { status: 500 });
    }
  }
  // 미적용(대기/이미 반려) → 그냥 REJECTED(원자적 전이)

