// ★이전(처리된) 검토 재결정★ — 실수 복구. 반려→다시 승인(편집 적용), 승인→되돌리기(적용 커밋 git revert).
async function reDecide(p: PastItem, action: "approve" | "reject") {
  const msg = action === "approve"
    ? `「${p.sourceTitle}」를 ★다시 승인★해 위키에 반영할까요? (이전에 반려했던 항목)`
    : `「${p.sourceTitle}」의 승인을 ★되돌릴까요?★\n적용했던 위키 변경을 git revert(새 커밋·이력 보존)로 원복합니다. 이후 그 페이지를 다른 사람이 또 고쳤으면 충돌로 중단될 수 있어요.`;
  if (!await confirmDialog(msg)) return;
  setBusy(p.jobId); setErr(null);
  try {
    const r = await fetch(`/api/review/${p.jobId}`, {
      method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ action }),
    });
    const d = await r.json();
    if (!r.ok) throw new Error(d.error || "처리에 실패했습니다.");
    await load(true); // 목록 갱신(대기/이전 재배치)
    onChanged?.();
  } catch (e) {
    setErr(e instanceof Error ? e.message : String(e));
  } finally {
    setBusy(null);
  }
}

