import { describe, it, expect } from "vitest";
import { isCommitHash } from "../lib/wiki/repo";

// 되돌리기/diff는 외부에서 받은 커밋 해시를 git 인자로 넘긴다 → 형식 검증이 1차 방어(인자 주입 차단).
describe("isCommitHash", () => {
  it("7~40 hex만 허용", () => {
    expect(isCommitHash("a1b2c3d")).toBe(true);
    expect(isCommitHash("0123456789abcdef0123456789abcdef01234567")).toBe(true);
    expect(isCommitHash("ABCDEF1")).toBe(true);
  });
  it("형식 외(짧음·비hex·옵션·공백·세미콜론)는 거부", () => {
    expect(isCommitHash("abc")).toBe(false);          // 너무 짧음
    expect(isCommitHash("g1b2c3d")).toBe(false);       // hex 아님
    expect(isCommitHash("--all")).toBe(false);
    expect(isCommitHash("a1b2c3d; rm -rf")).toBe(false);
    expect(isCommitHash("HEAD~1")).toBe(false);
    expect(isCommitHash("")).toBe(false);
  });
});

