const body = (
  <>
      <p className="set-note" style={{ marginTop: 0 }}>
        LLM이 모순·대체 가능성으로 보류한 인제스트입니다. 원본은 이미 보존돼 있고, <b>승인</b>하면 편집이 위키에 적용됩니다.
      </p>
      {/* 검토 게이트 임계(관리자만) — 신뢰도 < 임계인 인제스트는 자동 적용 대신 이 큐로. 높일수록 엄격. */}
      {thresh !== null && (
        <div className="au-limit" style={{ marginBottom: 12 }}>
          <span className="au-limit-lbl">자동 적용 임계 (신뢰도 ≥)</span>
          <input className="au-limit-input" type="number" min={0} max={100} step={5} value={threshInput}
            onChange={(e) => setThreshInput(e.target.value)} disabled={savingThresh} />
          <span style={{ color: "var(--color-text-tertiary)", fontSize: 13 }}>%</span>
          <button className="au-limit-save" onClick={saveThreshold} disabled={savingThresh || threshInput === String(Math.round(thresh * 100))}>
            <IconCheck size={14} />{savingThresh ? "저장 중…" : "저장"}
          </button>
          <span className="au-limit-cur">신뢰도 {Math.round(thresh * 100)}% 미만이면 검토 큐로(높일수록 엄격)</span>
        </div>
      )}
      {staleDays !== null && (
        <div className="au-limit" style={{ marginBottom: 12 }}>
          <span className="au-limit-lbl">오래된 페이지 기준</span>
          <input className="au-limit-input" type="number" min={0} step={30} value={staleInput}
            onChange={(e) => setStaleInput(e.target.value)} disabled={savingStale} />
          <span style={{ color: "var(--color-text-tertiary)", fontSize: 13 }}>일</span>
          <button className="au-limit-save" onClick={saveStale} disabled={savingStale || staleInput === String(staleDays)}>
            <IconCheck size={14} />{savingStale ? "저장 중…" : "저장"}
          </button>
          <span className="au-limit-cur">{staleDays > 0 ? `${staleDays}일 넘게 갱신 안 된 페이지를 아래에 표시(0=끔)` : "꺼짐"}</span>
        </div>
      )}
      {err && <div className="mat-banner err" style={{ marginBottom: 12 }}><IconAlertTriangle size={14} />{err}</div>}
      {loading ? (
        <div className="set-card">불러오는 중…</div>
      ) : items.length === 0 && promos.length === 0 ? (
        <div className="set-card" style={{ textAlign: "center", color: "var(--color-text-tertiary)" }}>검토 대기 항목이 없습니다.</div>
      ) : (
        <>
          {promos.length > 0 && (
            <>
              <div className="rev-section-head">승격 요청 ({promos.length})</div>
              {promos.map((p) => (
                <div key={`p${p.id}`} className="set-card rev-item">
                  <div className="rev-head">
                    <span className="rev-warn rev-promo"><IconArrowUp size={14} />승격 요청</span>
                    <span className="rev-scope">{p.fromName} → {promoTarget(p)}</span>
                  </div>
                  <div className="rev-title">{p.title}</div>
                  <div className="rev-summary">{p.path} → {promoTarget(p)} · 승인 시 그 범위 위키로 재인제스트</div>
                  <div className="rev-actions">
                    <button className="modal-btn ghost" disabled={pbusy === p.id} onClick={() => actPromo(p, "reject")}><IconX size={14} />반려</button>
                    <button className="modal-btn primary" disabled={pbusy === p.id} onClick={() => actPromo(p, "approve")}><IconCheck size={14} />{pbusy === p.id ? "처리 중…" : "승격"}</button>
                  </div>
                </div>
              ))}
              {items.length > 0 && <div className="rev-section-head">인제스트 검토 큐</div>}
            </>
          )}
          {items.map((it) => (
          <div key={it.jobId} className="set-card rev-item">
            <div className="rev-head">
              <span className="rev-warn"><IconAlertTriangle size={14} />검토 필요</span>
              <span className="rev-scope">{it.scopeName}</span>
              {typeof it.confidence === "number" && <span className="rev-conf">신뢰도 {(it.confidence * 100).toFixed(0)}%</span>}
              <a className="mat-act" href={`/api/materials/${it.sourceId}/raw`} target="_blank" rel="noreferrer" title="원본 열기" style={{ marginLeft: "auto" }}><IconExternalLink size={14} /></a>
            </div>
            <div className="rev-title">{it.sourceTitle} <span className="mat-ext">{it.sourceType}</span></div>
            {it.summary && <div className="rev-summary">{it.summary}</div>}
            {/* ★왜 검토가 필요한지★ — 모순이 아닌 사유(분석 모델이 요청·저신뢰 등)를 한 줄로 안내(사용자가 모르던 것). */}
            {it.reviewReason && (
              <div className="rev-reason"><IconInfoCircle size={13} style={{ verticalAlign: "-2px", marginRight: 4 }} />검토 사유: {it.reviewReason}</div>
            )}
            {/* ★모순 검증 게이트(B)★ — 왜 검토인지(기존 위키와 충돌)를 명시. 자동적용 대신 사람이 어느 쪽이 맞는지 결정. */}
            {it.contradictions && it.contradictions.length > 0 && (
              <div className="mat-banner err" style={{ display: "block", marginTop: 8 }}>
                <div style={{ fontWeight: 600, marginBottom: 4 }}><IconAlertTriangle size={14} style={{ verticalAlign: "-2px", marginRight: 4 }} />기존 위키와 모순 — 어느 쪽이 맞는지 확인하세요 <span style={{ fontWeight: 400, opacity: 0.85 }}>(승인 시 새 정보로 대체)</span></div>
                <ul style={{ margin: 0, paddingLeft: 18 }}>
                  {it.contradictions.map((c, i) => (
                    <li key={i}>
                      <b>{c.subject}</b>: 기존 「{c.existing}」{c.existingDate ? <span style={{ opacity: 0.8 }}> ({fmtWhen(c.existingDate)} 자료)</span> : ""} ↔ 새 자료 「{c.incoming}」<span style={{ opacity: 0.8 }}> ({fmtWhen(it.createdAt)} · 최신)</span>{c.page ? ` · ${c.page}` : ""}
                    </li>
                  ))}
                </ul>
              </div>
            )}
            {it.edits.length > 0 && (
              <div className="rev-changes">
                <button className="rev-diff-toggle" onClick={() => toggleDiff(it.jobId)}>
                  {openDiff.has(it.jobId) ? <IconChevronDown size={13} /> : <IconChevronRight size={13} />}
                  변경 {it.edits.length}건 미리보기
                </button>
                {openDiff.has(it.jobId) && (
                  diffBusy.has(it.jobId) && !diffData[it.jobId] ? (
                    <div className="rev-diff-loading">불러오는 중…</div>
                  ) : (
                    (diffData[it.jobId]?.edits ?? []).map((ed, i) => (
                      <div key={i} className="rev-diff-file">
                        <div className="rev-diff-head">
                          <b>{ed.op === "create" ? (ed.isNew ? "새 페이지" : "전체 교체") : "내용 추가"}</b>
                          <span className="rev-diff-path">{ed.path}</span>
                          <span className="rev-diff-stat">+{ed.diff.added}{ed.diff.removed ? ` −${ed.diff.removed}` : ""}</span>
                        </div>
                        <pre className="rev-diff-body">
                          {ed.diff.lines.map((l, k) => (
                            <div key={k} className={`diff-line ${l.type}`}>{`${l.type === "add" ? "+" : l.type === "del" ? "−" : " "} ${l.text}`}</div>
                          ))}
                          {ed.diff.truncated && <div className="diff-line ctx">… (이하 생략 — 변경이 너무 큼)</div>}
                        </pre>
                      </div>
                    ))
                  )
                )}
              </div>
            )}
            <div className="rev-actions">
              <button className="modal-btn ghost" disabled={busy === it.jobId} onClick={() => act(it, "reject")}><IconX size={14} />반려</button>
              <button className="modal-btn primary" disabled={busy === it.jobId} onClick={() => act(it, "approve")}><IconCheck size={14} />{busy === it.jobId ? "처리 중…" : "승인·적용"}</button>
            </div>
          </div>
          ))}
        </>
      )}
      {flagged.length > 0 && (
        <>
          <div className="rev-section-head" style={{ marginTop: 16 }}>👎 부정평가가 많은 페이지 — 검토 1순위 ({flagged.length})</div>
          <div className="rev-stale-list">
            {flagged.map((f) => (
              <div key={f.path} className="rev-stale">
                <span className="rev-stale-title">{f.title}</span>
                <span className="rev-stale-meta">{f.scopeName} · <b>👎 {f.downvotes}회</b></span>

