{/* 회의 액션아이템(할 일) 모달 — 가로지르는 조회 + 완료 체크. 회의 분석이 적재(action_item). */}
{actionsOpen && (
  <div className="modal-overlay" onClick={() => setActionsOpen(false)}>
    <div className="set-modal-card" onClick={(e) => e.stopPropagation()}>
      <div className="set-modal-head"><span className="set-modal-title"><IconChecklist size={16} style={{ verticalAlign: "-3px", marginRight: 6 }} />할 일 — 회의 액션아이템</span><button className="modal-x" onClick={() => setActionsOpen(false)} aria-label="닫기"><IconX size={17} /></button></div>
      <p className="set-note" style={{ marginTop: 0 }}>이 룸의 회의에서 나온 할 일입니다. 담당·기한은 ★후보★(실제 담당은 회의록에서 확인). 체크하면 완료 처리됩니다.</p>
      {actionsLoading ? <div className="set-note">불러오는 중…</div>
        : actionItems.length === 0 ? <div className="set-note">아직 액션아이템이 없습니다. 회의(음성·영상)를 업로드·분석하면 여기에 모입니다.</div>
        : <ul className="wt-actions-list">
            {actionItems.map((it) => (
              <li key={it.id} className={`wt-action${it.status === "done" ? " done" : ""}`}>
                <button className="wt-action-check" onClick={() => toggleAction(it.id, it.status)} title={it.status === "done" ? "완료 해제" : "완료"} aria-label="완료 토글">
                  {it.status === "done" ? <IconCheck size={14} /> : <span className="wt-action-box" />}
                </button>
                <div className="wt-action-body">
                  <div className="wt-action-task">{it.task}</div>
                  <div className="wt-action-meta">
                    {it.owner && <span title="담당 후보">👤 {it.owner}</span>}
                    {it.deadline && <span title="기한">📅 {it.deadline}</span>}
                    {it.timestamp && <span title="회의 시점">⏱ {it.timestamp}</span>}
                    {it.pagePath && <button className="wt-action-link" onClick={() => { setActionsOpen(false); onLink(it.pagePath!); }} title="회의록 페이지 열기"><IconExternalLink size={11} />회의록</button>}
                  </div>
                </div>
              </li>
            ))}
          </ul>}
    </div>
  </div>
)}
{/* 내보내기 모달 — 컴팩트·X만 */}
{canByo && exportModal && (
  <div className="modal-overlay" onClick={() => !exporting && setExportModal(false)}>
    <div className="modal-card byo-modal" onClick={(e) => e.stopPropagation()}>
      <div className="modal-head">
        <h2 className="modal-title">내보내기</h2>
        <button className="modal-x" onClick={() => setExportModal(false)} aria-label="닫기"><IconX size={16} /></button>
      </div>
      <p className="modal-desc">이 위키를 Obsidian용 markdown으로 내려받아요. 풀면 바로 vault로 열려요.</p>
      <label className="web-toggle" title="페이지가 인용한 이미지·PDF 원본도 zip에 함께 담아요(용량 ↑).">
        <input type="checkbox" role="switch" aria-checked={exportAssets} checked={exportAssets} onChange={(e) => setExportAssets(e.target.checked)} disabled={exporting} />
        <span className="web-toggle-label">이미지·PDF 원본도 포함</span>
      </label>
      <div className="modal-actions">
        <button className="modal-btn primary" onClick={doExport} disabled={exporting}><IconFileExport size={14} />{exporting ? "내보내는 중…" : "내려받기"}</button>
      </div>
    </div>
  </div>
)}
{/* 가져오기 모달 — 컴팩트·X만·버튼 하나(폴더 선택) */}
{canByo && importModal && (
  <div className="modal-overlay" onClick={() => !importing && setImportModal(false)}>
    <div className="modal-card byo-modal" onClick={(e) => e.stopPropagation()}>
