      <div className="modal-actions">
        <button className="modal-btn primary" onClick={() => folderInputRef.current?.click()} disabled={importing}><IconFolder size={14} />{importing ? "가져오는 중…" : "zip 또는 폴더 선택"}</button>
      </div>
    </div>
  </div>
)}
<div className="wt-tree">
