    {files.length > 1 && <button className="wt-graph-btn" onClick={() => setGraphOpen(true)} title="지식 그래프 — 페이지들이 서로 어떻게 이어지는지 한눈에 봅니다"><IconAffiliate size={13} />그래프</button>}
    {files.length > 1 && canManage && <button className="wt-graph-btn" onClick={() => setHygieneOpen(true)} title="위키 점검 — 외톨이·끊긴 링크·겹치는 페이지를 찾아 정리 제안"><IconStethoscope size={13} />점검</button>}
    <button className="wt-graph-btn" onClick={openActions} title="할 일 — 이 룸의 회의에서 나온 액션아이템(담당·기한). 완료 체크 가능"><IconChecklist size={13} />할 일</button>
