 *   ★N+1 회피★: 여러 건이면 호출부에서 Map 캐시로 메모이즈(같은 scope 반복 조회 방지).
 */
export async function teamScopeName(teamScope: string): Promise<string> {
  if (teamScope === "common") return "회사 공통";
  if (teamScope.startsWith("personal/")) return "개인 위키";
  if (teamScope.startsWith("project-")) {
    const p = await prisma.project.findUnique({ where: { slug: teamScope.slice("project-".length) }, select: { name: true } });
    return p?.name ?? teamScope;
  }
  return teamScope;
}

