import { prisma } from "@/lib/db";
import type { User } from "@prisma/client";

// ── ACL 단일 계산처 (docs/07 §2, docs/11 §6, REQ-AUTH-004) ──────────
// "사용자의 허용 scope 집합"을 한 곳에서 계산한다. 질의 입력·페이지 로드·인제스트 적용·
// 누적 파일링 등 모든 강제지점이 이 함수를 공용 호출한다.

export type ScopeKind = "common" | "personal" | "project";

export interface AllowedScope {
  id: string; // 'common' | 'personal:<userId>' | 'project-<slug>'
  kind: ScopeKind;
  name: string;
  description?: string | null; // 룸 설명(project만) — 헤더에서 이름 옆에 표시
  isOwner?: boolean;
  archived?: boolean; // 아카이브된 룸(읽기 전용 열람용) — allowedScopes에는 없고 archivedScopes로만 노출
  parentScope?: string | null; // 상위 룸 scope id(서브룸) — 사이드바 중첩·헤더 표시용. 최상위=null
  inheritsCommon?: boolean; // 질의 시 회사 공통도 항상 참조하는 룸인지
}

/** scope id 규칙 */
export const personalScopeId = (userId: number) => `personal:${userId}`;
export const projectScopeId = (slug: string) => `project-${slug}`;

/** 사용자가 접근 가능한 scope 목록(공통 + 내 룸 + 개인). */
export async function allowedScopes(user: User): Promise<AllowedScope[]> {
  const memberships = await prisma.projectMembership.findMany({
    where: { userId: user.id },
    include: { project: { include: { parent: { select: { slug: true } } } } },
    orderBy: { createdAt: "asc" },
  });
  const rooms: AllowedScope[] = memberships
    .filter((m) => !m.project.archivedAt)
    .map((m) => ({
      id: projectScopeId(m.project.slug),
      kind: "project",
      name: m.project.name,
      description: m.project.description,
      isOwner: m.role === "OWNER",
      parentScope: m.project.parent ? projectScopeId(m.project.parent.slug) : null,
      inheritsCommon: m.project.inheritsCommon,
    }));
  return [
    { id: "common", kind: "common", name: "회사공통" },
    ...rooms,
    { id: personalScopeId(user.id), kind: "personal", name: "내 위키" },
  ];
}

/**
 * 사용자가 멤버였던 ★아카이브된★ 룸 목록(읽기 전용 열람용). allowedScopes에서는 제외되므로
 * 사이드바 '아카이브 룸' 섹션이 이 함수를 따로 호출한다. 각 항목에 archived:true 부여.
 */
export async function archivedScopes(user: User): Promise<AllowedScope[]> {
  const memberships = await prisma.projectMembership.findMany({
    where: { userId: user.id, project: { archivedAt: { not: null } } },
    include: { project: true },
    orderBy: { createdAt: "asc" },
  });
  return memberships.map((m) => ({
    id: projectScopeId(m.project.slug),
    kind: "project" as const,
    name: m.project.name,
    description: m.project.description,
    isOwner: m.role === "OWNER",
    archived: true,
  }));
}

/** 허용 scope 밖이면 throw (ACL 강제). */
export async function assertScopeAllowed(user: User, scopeId: string): Promise<void> {
  const ok = (await allowedScopes(user)).some((s) => s.id === scopeId);
  if (!ok) throw new Error(`scope 접근 거부: ${scopeId}`);
}

/**
 * ★읽기 전용★ 접근 가드 — 활성 scope는 그대로 허용하고, 추가로 사용자가 멤버였던 아카이브 룸의
 * 위키 ★열람★(쓰기 아님)을 허용한다. 쓰기·질의 경로는 여전히 assertScopeAllowed/canManageScope를
 * 써서 아카이브 룸을 차단한다(방어선). docs/07 §2, docs/11 §3.
 */
export async function assertScopeReadable(user: User, scopeId: string): Promise<void> {
  if ((await allowedScopes(user)).some((s) => s.id === scopeId)) return; // 활성 scope
  if (scopeId.startsWith("project-")) {
    const project = await prisma.project.findUnique({ where: { slug: scopeId.slice("project-".length) } });
    if (project?.archivedAt) {
      if (user.role === "ADMIN") return;
      const m = await prisma.projectMembership.findUnique({
        where: { userId_projectId: { userId: user.id, projectId: project.id } },
      });
      if (m) return; // 멤버였던 아카이브 룸 → 읽기 허용
    }
  }
  throw new Error(`scope 접근 거부: ${scopeId}`);
}

/**
 * 룸 ★관리 권한★(아카이브·편집·영구삭제용) — ADMIN | 개인위키 본인 | 룸 OWNER. common = ADMIN만.
 * teamScope = 위키 디렉터리 접두(scopeWikiPrefix 결과: 'common'·'personal/<id>'·'project-<slug>').
 * (자료 삭제의 기존 canDelete에서 ★업로더 경로를 뺀★ = "룸 관리자만".)
 */
export async function canManageScope(user: User, teamScope: string): Promise<boolean> {
  if (user.role === "ADMIN") return true;
  if (teamScope === `personal/${user.id}`) return true;
  if (teamScope.startsWith("project-")) {
    const project = await prisma.project.findUnique({ where: { slug: teamScope.slice("project-".length) } });
    if (!project || project.archivedAt) return false;
    const m = await prisma.projectMembership.findUnique({
      where: { userId_projectId: { userId: user.id, projectId: project.id } },
    });
    return m?.role === "OWNER";
  }
  return false; // common = ADMIN만(위에서 처리)
}

/**
 * ★인용 출처의 범위 라벨★ (A-2, 표시 전용 — ACL 판단 아님). 인용된 위키 경로가 현재 질의 범위 기준으로
 * 어디서 왔는지 사람이 읽는 한 단어 라벨로. cross-scope 답에서 '이 방 vs 회사 공통 vs 상위 방'을 구분.
 * path 예: 'common/entities/x.md' → 회사 공통, 'project-foo/topics/y.md' → 이 방/상위 방.
 * currentWikiScope = scopeWikiPrefix 결과(common·personal/<id>·project-<slug>).
 */
export function scopePathLabel(relPath: string, currentWikiScope: string): string {
  const norm = relPath.split(/[\\/]+/).join("/");
  if (norm === "common" || norm.startsWith("common/")) return "회사 공통";
  if (norm.startsWith("personal/")) return "내 위키";
  if (norm.startsWith("project-")) {
    const seg = norm.split("/")[0]; // project-<slug>
    return seg === currentWikiScope ? "이 방" : "상위 방";
  }
  return "";
}

/** scope id → 위키 디렉터리 경로(파일시스템 안전). 'personal:7' → 'personal/7'. */
export function scopeWikiPrefix(scopeId: string): string {
  if (scopeId === "common") return "common";
  if (scopeId.startsWith("personal:")) return `personal/${scopeId.slice("personal:".length)}`;
  return scopeId; // project-<slug>
}

/**
 * ★질의가 읽을 범위 체인★ — 서브룸 계층 상속(자기 → 부모 → 조부모 …). 형제는 절대 포함 안 됨.
 * 인자·반환 모두 ★위키 디렉터리 경로★(project-<slug> · common · personal/<id>).
 * ★회사 공통(common)은 여기서 자동 추가하지 않는다★ — 공통 포함은 ★질의 탭의 per-query 토글(includeCommon)★로만
 *   제어한다(룸 단위 inheritsCommon 설정은 폐기 — 룸 설정과 질의 토글이 충돌·중복되던 문제 해소).
 * 사이클·과도한 깊이는 가드(seen + 최대 10단계). 읽기 전용 확장이며 쓰기(인제스트)는 영향 없음.
 */
export async function resolveQueryScopes(wikiScope: string): Promise<string[]> {
  if (!wikiScope.startsWith("project-")) return [wikiScope]; // common · personal/<id> = 단일 범위
  const out: string[] = [];
  const seen = new Set<string>();
  let slug: string | null = wikiScope.slice("project-".length);
  while (slug && !seen.has(slug) && out.length < 10) {
    const cur: string = slug; // const로 좁혀 where 타입의 순환 추론 방지
    seen.add(cur);
    out.push(`project-${cur}`);
    const p = await prisma.project.findUnique({
      where: { slug: cur },
      select: { parent: { select: { slug: true } } },
    });
    if (!p) break;
    slug = p.parent?.slug ?? null;
  }
  return out;
}

import { prisma } from "./db";

// 인앱 알림 (A-4 토대) — 종🔔 배지·드로어용 서버 헬퍼. 정기 잡(오래됨·다이제스트)이 createNotification으로
// 사용자별 알림을 멱등하게 만들고, UI는 list/markRead로 읽는다. ★알림은 사용자별(userId)★ — 목록은 본인 것만(ACL).

export interface NotifInput {
  userId: number;
  type: string;          // 'STALE' | 'DIGEST' | 'LINT' | 'FEEDBACK' …
  title: string;
  body?: string;
  linkPath?: string;     // 클릭 시 이동(위키 경로·검토 큐 등)
  teamScope?: string;
  dedupKey: string;      // 멱등 키(type+scope+대상+주차) — 같은 잡 재실행 시 중복 알림 방지
}

/** 멱등 생성 — 같은 dedupKey면 무시(중복 알림 방지). 정기 잡이 호출. */
export async function createNotification(n: NotifInput): Promise<void> {
  await prisma.notification.upsert({
    where: { dedupKey: n.dedupKey },
    create: {
      userId: n.userId, type: n.type, title: n.title,
      body: n.body ?? null, linkPath: n.linkPath ?? null, teamScope: n.teamScope ?? null, dedupKey: n.dedupKey,
    },
    update: {}, // 이미 있으면 그대로(재실행 멱등)
  });
}

/** 내 알림 목록 + 안읽음 수(본인 것만). */
export async function listNotifications(userId: number, limit = 30) {
  const [items, unread] = await Promise.all([
    prisma.notification.findMany({
      where: { userId }, orderBy: { id: "desc" }, take: limit,
      select: { id: true, type: true, title: true, body: true, linkPath: true, teamScope: true, readAt: true, createdAt: true },
    }),
    prisma.notification.count({ where: { userId, readAt: null } }),
  ]);
  return { items, unread };
}

/** 읽음 처리 — ids 주면 그 항목만, 없으면 안읽음 전체. 본인 것만. */
export async function markRead(userId: number, ids?: number[]): Promise<void> {
  await prisma.notification.updateMany({
    where: { userId, readAt: null, ...(ids && ids.length ? { id: { in: ids } } : {}) },
    data: { readAt: new Date() },
  });
}

