21	  for (const rel of changedPaths) {
22	    if (!/\/topics\/[^/]+\.md$/.test(rel)) continue; // 회의 구조는 topics 페이지에
23	    let body: string;
24	    try { body = await fs.readFile(wikiAbsPath(rel), "utf8"); } catch { continue; }
25	    for (const it of parseActionItems(body)) parsed.push({ ...it, pagePath: rel });
26	  }
27	
28	  const existing = await prisma.actionItem.findMany({ where: { sourceId }, select: { stableKey: true, status: true } });
29	  const statusByKey = new Map(existing.map((e) => [e.stableKey, e.status]));
30	  const seen = new Set<string>();
31	  for (const it of parsed) {
32	    const key = actionStableKey(sourceId, it.task);
33	    if (seen.has(key)) continue; // 같은 자료 내 동일 task 중복 방지
34	    seen.add(key);
35	    const prevStatus = statusByKey.get(key); // 사용자가 토글했으면 보존
36	    await prisma.actionItem.upsert({
37	      where: { stableKey: key },
38	      create: { stableKey: key, sourceId, scope, pagePath: it.pagePath, task: it.task, owner: it.owner, deadline: it.deadline, timestamp: it.timestamp, status: it.done ? "done" : "open" },
39	      update: { scope, pagePath: it.pagePath, task: it.task, owner: it.owner, deadline: it.deadline, timestamp: it.timestamp, status: prevStatus ?? (it.done ? "done" : "open") },
40	    });
41	  }
42	  // 더 이상 본문에 없는 항목 제거(이 자료에서 사라진 액션).
43	  if (seen.size) await prisma.actionItem.deleteMany({ where: { sourceId, stableKey: { notIn: [...seen] } } });
44	  else await prisma.actionItem.deleteMany({ where: { sourceId } });
45	}
