import { createHash } from "node:crypto";
import { promises as fs } from "node:fs";
import { prisma } from "./db";
import { wikiAbsPath } from "./wiki/paths";
import { parseActionItems } from "./meeting";

// 회의 지식화 고도화 — 회의 분석이 쓴 본문(## 액션아이템)을 action_item 메타DB로 동기화.
//   ★멱등★: 재분석해도 stableKey(source+정규화 task)로 매칭 → ★사용자가 토글한 status(done)는 보존★,
//   사라진 항목만 삭제. 본문이 단일 진실(verbatim), DB는 가로지르는 조회/완료체크용 투영.

function normTask(task: string): string {
  return task.toLowerCase().replace(/\s+/g, " ").trim();
}
export function actionStableKey(sourceId: number, task: string): string {
  return createHash("sha256").update(`${sourceId}\n${normTask(task)}`).digest("hex").slice(0, 32);
}

// 변경된 페이지들 중 topics(회의) 페이지의 ## 액션아이템을 읽어 적재. best-effort(실패해도 인제스트 무영향).
export async function syncMeetingActionItems(sourceId: number, scope: string, changedPaths: string[]): Promise<void> {
  const parsed: Array<{ task: string; owner: string | null; deadline: string | null; timestamp: string | null; done: boolean; pagePath: string }> = [];
  for (const rel of changedPaths) {
    if (!/\/topics\/[^/]+\.md$/.test(rel)) continue; // 회의 구조는 topics 페이지에
    let body: string;
    try { body = await fs.readFile(wikiAbsPath(rel), "utf8"); } catch { continue; }
    for (const it of parseActionItems(body)) parsed.push({ ...it, pagePath: rel });
  }

  const existing = await prisma.actionItem.findMany({ where: { sourceId }, select: { stableKey: true, status: true } });
  const statusByKey = new Map(existing.map((e) => [e.stableKey, e.status]));
  const seen = new Set<string>();
  for (const it of parsed) {
    const key = actionStableKey(sourceId, it.task);
    if (seen.has(key)) continue; // 같은 자료 내 동일 task 중복 방지
    seen.add(key);
    const prevStatus = statusByKey.get(key); // 사용자가 토글했으면 보존
    await prisma.actionItem.upsert({
      where: { stableKey: key },
      create: { stableKey: key, sourceId, scope, pagePath: it.pagePath, task: it.task, owner: it.owner, deadline: it.deadline, timestamp: it.timestamp, status: it.done ? "done" : "open" },
      update: { scope, pagePath: it.pagePath, task: it.task, owner: it.owner, deadline: it.deadline, timestamp: it.timestamp, status: prevStatus ?? (it.done ? "done" : "open") },
    });
  }
  // 더 이상 본문에 없는 항목 제거(이 자료에서 사라진 액션).
  if (seen.size) await prisma.actionItem.deleteMany({ where: { sourceId, stableKey: { notIn: [...seen] } } });
  else await prisma.actionItem.deleteMany({ where: { sourceId } });
}

