import { NextResponse } from "next/server";
import { getSessionUser } from "@/lib/auth/session";
import { allowedScopes } from "@/lib/acl/scope";
import { prisma } from "@/lib/db";

// 회의 액션아이템 — 접근 가능한 scope의 항목을 가로질러 조회(미완료 우선). 회의 분석이 적재(lib/actionItems).
export const runtime = "nodejs";

export async function GET(req: Request) {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "로그인이 필요합니다." }, { status: 401 });
  const scopesList = await allowedScopes(user);
  const nameById = new Map(scopesList.map((s) => [s.id, s.name]));
  const ids = scopesList.map((s) => s.id);
  ids.push(`personal/${user.id}`); // 개인 위키 회의도 포함
  nameById.set(`personal/${user.id}`, "내 위키");

  const url = new URL(req.url);
  const reqScope = url.searchParams.get("scope");
  const onlyOpen = url.searchParams.get("open") === "1";
  const where = {
    scope: reqScope && ids.includes(reqScope) ? reqScope : { in: ids },
    ...(onlyOpen ? { status: "open" } : {}),
  };
  const rows = await prisma.actionItem.findMany({
    where,
    orderBy: [{ status: "desc" }, { createdAt: "desc" }], // open(>done) 먼저, 최신 먼저
    take: 500,
  });
  const items = rows.map((r) => ({
    id: r.id, task: r.task, owner: r.owner, deadline: r.deadline, timestamp: r.timestamp,
    status: r.status, scope: r.scope, scopeName: nameById.get(r.scope) ?? r.scope,
    pagePath: r.pagePath, sourceId: r.sourceId, createdAt: r.createdAt.toISOString(),
  }));
  return NextResponse.json({ items });
}

