31	  } catch {
32	    return NextResponse.json({ error: "접근 권한이 없는 scope입니다." }, { status: 403 });
33	  }
34	
35	  const wikiScope = scopeWikiPrefix(scope);
36	
37	  // 비용 상한(REQ-OPS-006): 오늘 토큰 한도(사용자/룸/전체) 초과 시 차단
38	  const budget = await checkDailyBudget(user.id, wikiScope);
39	  if (budget.exceeded) {
40	    return NextResponse.json({ error: budgetExceededMessage(budget) }, { status: 429 });
41	  }
42	
43	  try {
44	    // 대화 세션 로드/생성 (소유자 본인 것만)
45	    let conv =
46	      typeof conversationId === "number"
47	        ? await prisma.conversation.findFirst({ where: { id: conversationId, userId: user.id } })
48	        : null;
49	    if (!conv) {
50	      conv = await prisma.conversation.create({
51	        data: { scope: wikiScope, userId: user.id, title: question.slice(0, 40) },
52	      });
53	    }
54	
55	    // 이전 메시지(멀티턴 히스토리)
56	    const prior = await prisma.message.findMany({
57	      where: { conversationId: conv.id },
58	      orderBy: { id: "asc" },
59	      take: 20,
60	    });
61	    // ★ 위키 경로 히스토리에서는 웹 출처(webSourced) 답변을 제외 — 외부 웹 내용이
62	    //   위키 답변(=git에 파일링됨)에 절대 흘러들지 않게(REQ-SEARCH-003). 웹 경로는 전체 사용.
63	    const wikiHistory = prior
64	      .filter((m) => m.webSourced !== true)
65	      .map((m) => ({ role: m.role as "user" | "assistant", content: m.content }));
66	    const webHistory = prior.map((m) => ({ role: m.role as "user" | "assistant", content: m.content }));
67	
68	    // 사용자 메시지 기록
69	    await prisma.message.create({ data: { conversationId: conv.id, role: "user", content: question } });
70	
71	    // 사용자가 채팅에서 고른 모델(있으면) 검증 후 적용. 미허용/비활성이면 기본값으로 폴백.
72	    const picked = await resolveQueryModel(typeof model === "string" ? model : undefined);
73	
74	    // ── 웹검색 경로(옵트인·세션격리) ── git 위키·queries에 미진입(REQ-SEARCH-003)
75	    // 선택 모델의 공급자에 따라 Claude(서버 web_search) 또는 Gemini(Google 그라운딩)로 위임.
76	    if (web) {
77	      // ① 재사용 캐시(독립 질문만): 같은 룸에서 최근 거의 동일한 웹질의 답이 있고 그 뒤 새 자료가 없으면
78	      //   재사용해 ★웹검색 토큰 0★. 자료가 쌓였으면(freshness) 재사용 안 하고 다시 검색해 더 나은 답.
79	      if (webHistory.length === 0) {
80	        const reuse = await tryReuseWebAnswer(wikiScope, question);
81	        if (reuse) {
82	          await prisma.message.create({ data: { conversationId: conv.id, role: "assistant", content: reuse.answerMd, webSourced: true } });
83	          await prisma.conversation.update({ where: { id: conv.id }, data: { title: conv.title ?? question.slice(0, 40) } });
84	          return NextResponse.json({
85	            conversationId: conv.id, answer: reuse.answerMd, answered: true, web: true, reused: true,
86	            budgetWarn: budget.warn,
87	            citations: reuse.citations.map((c) => ({ type: "web", label: c.title, url: c.url })),
88	          });
89	        }
90	      }
91	      // ② ★룸 위키 우선 + 웹 보강★ — 이 룸의 관련 위키를 컨텍스트로 넣는다(룸이 비면 text="" → 웹-전용 폴백).
92	      const room = await buildRoomContextForWeb(wikiScope, question);
93	      const wr = await answerWithWebSearch({ question, history: webHistory, provider: picked.provider, model: picked.model, roomContext: room.text || undefined });
94	      await prisma.message.create({
95	        data: { conversationId: conv.id, role: "assistant", content: wr.answer, webSourced: true },
96	      });
97	      await prisma.conversation.update({ where: { id: conv.id }, data: { title: conv.title ?? question.slice(0, 40) } });
98	      await recordUsage({ userId: user.id, scope: wikiScope, kind: "websearch", model: picked.model, inputTokens: wr.usage.inputTokens, outputTokens: wr.usage.outputTokens });
99	      // ③ ★웹 Q&A를 QueryLog에 저장★(webSourced — 재사용 캐시 전용, git 위키·검색·위키질의 미진입). 독립 질문·실답만.
100	      if (webHistory.length === 0 && wr.answer.trim()) {
101	        await recordWebQuery({ scope: wikiScope, userId: user.id, question, answerMd: wr.answer, citations: wr.citations, inputTokens: wr.usage.inputTokens, outputTokens: wr.usage.outputTokens });
102	      }
103	      return NextResponse.json({
104	        conversationId: conv.id,
105	        answer: wr.answer,
106	        answered: true,
107	        web: true,
108	        budgetWarn: budget.warn,
109	        usedModel: picked.model,
110	        usedProvider: picked.provider,
111	        citations: wr.citations.map((c) => ({ type: "web", label: c.title, url: c.url })),
112	      });
113	    }
114	
115	    // ── 위키 경로 ── (ACL 강제지점2: loadPages가 wikiScope 페이지만 로드)
116	    const result = await answerQuery({ scope: wikiScope, question, userId: user.id, history: wikiHistory, model: picked.model, provider: picked.provider, think: picked.think, includeCommon: includeCommon === true });
117	
118	    // 어시스턴트 메시지 기록 + 대화 touch
119	    await prisma.message.create({
120	      data: { conversationId: conv.id, role: "assistant", content: result.answerMd, queryLogId: result.queryId },
121	    });
122	    await prisma.conversation.update({ where: { id: conv.id }, data: { title: conv.title ?? question.slice(0, 40) } });
123	
124	    // 출처 칩 라벨은 ★한국어 제목★(frontmatter title)으로 — 영문 파일명(slug) 대신. 위키 트리·인용과 동일 규칙.
125	    const citeTitles = await pageTitles(result.citedPaths);
126	    // 인용 근거 — 각 인용 페이지에서 질문과 가장 겹치는 문장(왜 인용됐는지). 로컬 계산.
127	    const citeSnippets: Record<string, string> = {};
128	    await Promise.all(result.citedPaths.map(async (p) => {
129	      try { citeSnippets[p] = bestSupportingSentence(await fs.readFile(wikiAbsPath(p), "utf8"), question); } catch { /* 페이지 없으면 생략 */ }
130	    }));
131	    // ★근거 신뢰도(A-1)★ — 인용 수 + 인용 페이지 최신성으로 강/보통/약(LLM 호출 0, 있는 데이터 재사용).
132	    //   인용 페이지의 가장 최근 갱신일(WikiDoc.updatedAt)로 '오래됨' 여부를 본다.
133	    let freshestUpdatedDays: number | null = null;
134	    if (result.citedPaths.length) {
135	      const docs = await prisma.wikiDoc.findMany({ where: { path: { in: result.citedPaths } }, select: { updatedAt: true } });
136	      if (docs.length) {
137	        const newest = Math.max(...docs.map((d) => d.updatedAt.getTime()));
138	        freshestUpdatedDays = Math.floor((Date.now() - newest) / 86_400_000);
139	      }
140	    }
141	    const evidence = evidenceLevel({ citedCount: result.citedPaths.length, freshestUpdatedDays });
