import { prisma } from "./db";
import { teamScopeName } from "./acl/scope";

// 인앱 알림 (A-4 토대) — 종🔔 배지·드로어용 서버 헬퍼. 정기 잡(오래됨·다이제스트)이 createNotification으로
// 사용자별 알림을 멱등하게 만들고, UI는 list/markRead로 읽는다. ★알림은 사용자별(userId)★ — 목록은 본인 것만(ACL).

export interface NotifInput {
  userId: number;
  type: string;          // 'STALE' | 'DIGEST' | 'LINT' | 'FEEDBACK' …
  title: string;
  body?: string;
  linkPath?: string;     // 클릭 시 이동(위키 경로·검토 큐 등)
  teamScope?: string;
  dedupKey: string;      // 멱등 키(type+scope+대상+주차) — 같은 잡 재실행 시 중복 알림 방지
}

/** 멱등 생성 — 같은 dedupKey면 무시(중복 알림 방지). 정기 잡이 호출. */
export async function createNotification(n: NotifInput): Promise<void> {
  await prisma.notification.upsert({
    where: { dedupKey: n.dedupKey },
    create: {
      userId: n.userId, type: n.type, title: n.title,
      body: n.body ?? null, linkPath: n.linkPath ?? null, teamScope: n.teamScope ?? null, dedupKey: n.dedupKey,
    },
    update: {}, // 이미 있으면 그대로(재실행 멱등)
  });
}

/** 내 알림 목록 + 안읽음 수(본인 것만). 각 항목에 ★사람이 읽는 룸 이름(scopeName)★을 붙인다(드로어 배지용). */
export async function listNotifications(userId: number, limit = 30) {
  const [rows, unread] = await Promise.all([
    prisma.notification.findMany({
      where: { userId }, orderBy: { id: "desc" }, take: limit,
      select: { id: true, type: true, title: true, body: true, linkPath: true, teamScope: true, readAt: true, createdAt: true },
    }),
    prisma.notification.count({ where: { userId, readAt: null } }),
  ]);
  // teamScope → 룸 이름(메모이즈로 N+1·중복 project 조회 회피).
  const nameCache = new Map<string, string>();
  const items = await Promise.all(rows.map(async (n) => {
    let scopeName: string | null = null;
    if (n.teamScope) {
      if (!nameCache.has(n.teamScope)) nameCache.set(n.teamScope, await teamScopeName(n.teamScope));
      scopeName = nameCache.get(n.teamScope)!;
    }
    return { ...n, scopeName };
  }));
  return { items, unread };
}

/** 읽음 처리 — ids 주면 그 항목만, 없으면 안읽음 전체. 본인 것만. */
export async function markRead(userId: number, ids?: number[]): Promise<void> {
  await prisma.notification.updateMany({
    where: { userId, readAt: null, ...(ids && ids.length ? { id: { in: ids } } : {}) },
    data: { readAt: new Date() },
  });
}

