import { NextResponse } from "next/server";
import { getSessionUser } from "@/lib/auth/session";
import { assertScopeAllowed, scopeWikiPrefix, scopePathLabel } from "@/lib/acl/scope";
import { prisma } from "@/lib/db";
import { answerQuery, buildRoomContextForWeb, tryReuseWebAnswer, recordWebQuery } from "@/lib/query";
import { pageTitles } from "@/lib/wiki/context";
import { answerWithWebSearch } from "@/lib/websearch";
import { checkDailyBudget, recordUsage, budgetExceededMessage } from "@/lib/cost";
import { resolveQueryModel } from "@/lib/models";
import { promises as fs } from "node:fs";
import { wikiAbsPath } from "@/lib/wiki/paths";
import { bestSupportingSentence } from "@/lib/wiki/cite";
import { evidenceLevel } from "@/lib/wiki/evidence";

// 질의 탭 ↔ 실제 LLM. 세션 + ACL(강제지점1) + 대화 세션(멀티턴) + 출처 질의(Opus). docs/07.
export const runtime = "nodejs";
export const maxDuration = 300;

export async function POST(req: Request) {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "로그인이 필요합니다." }, { status: 401 });

  const { scope, question, conversationId, web, model, includeCommon } = await req.json();
  if (typeof scope !== "string" || typeof question !== "string" || !question.trim()) {
    return NextResponse.json({ error: "scope·question이 필요합니다." }, { status: 400 });
  }

  // ACL 강제지점1: 질의 입력 — 허용 scope가 아니면 거부
  try {
    await assertScopeAllowed(user, scope);
  } catch {
    return NextResponse.json({ error: "접근 권한이 없는 scope입니다." }, { status: 403 });
  }

  const wikiScope = scopeWikiPrefix(scope);

  // 비용 상한(REQ-OPS-006): 오늘 토큰 한도(사용자/룸/전체) 초과 시 차단
  const budget = await checkDailyBudget(user.id, wikiScope);
  if (budget.exceeded) {
    return NextResponse.json({ error: budgetExceededMessage(budget) }, { status: 429 });
  }

  try {
    // 대화 세션 로드/생성 (소유자 본인 것만)
    let conv =
      typeof conversationId === "number"
        ? await prisma.conversation.findFirst({ where: { id: conversationId, userId: user.id } })
        : null;
    if (!conv) {
      conv = await prisma.conversation.create({
        data: { scope: wikiScope, userId: user.id, title: question.slice(0, 40) },
      });
    }

    // 이전 메시지(멀티턴 히스토리)
    const prior = await prisma.message.findMany({
      where: { conversationId: conv.id },
      orderBy: { id: "asc" },
      take: 20,
    });
    // ★ 위키 경로 히스토리에서는 웹 출처(webSourced) 답변을 제외 — 외부 웹 내용이
    //   위키 답변(=git에 파일링됨)에 절대 흘러들지 않게(REQ-SEARCH-003). 웹 경로는 전체 사용.
    const wikiHistory = prior
      .filter((m) => m.webSourced !== true)
      .map((m) => ({ role: m.role as "user" | "assistant", content: m.content }));
    const webHistory = prior.map((m) => ({ role: m.role as "user" | "assistant", content: m.content }));

    // 사용자 메시지 기록
    await prisma.message.create({ data: { conversationId: conv.id, role: "user", content: question } });

    // 사용자가 채팅에서 고른 모델(있으면) 검증 후 적용. 미허용/비활성이면 기본값으로 폴백.
    const picked = await resolveQueryModel(typeof model === "string" ? model : undefined);

    // ── 웹검색 경로(옵트인·세션격리) ── git 위키·queries에 미진입(REQ-SEARCH-003)
    // 선택 모델의 공급자에 따라 Claude(서버 web_search) 또는 Gemini(Google 그라운딩)로 위임.
    if (web) {
      // ① 재사용 캐시(독립 질문만): 같은 룸에서 최근 거의 동일한 웹질의 답이 있고 그 뒤 새 자료가 없으면
      //   재사용해 ★웹검색 토큰 0★. 자료가 쌓였으면(freshness) 재사용 안 하고 다시 검색해 더 나은 답.
      if (webHistory.length === 0) {
        const reuse = await tryReuseWebAnswer(wikiScope, question);
        if (reuse) {
          await prisma.message.create({ data: { conversationId: conv.id, role: "assistant", content: reuse.answerMd, webSourced: true } });
          await prisma.conversation.update({ where: { id: conv.id }, data: { title: conv.title ?? question.slice(0, 40) } });
          return NextResponse.json({
            conversationId: conv.id, answer: reuse.answerMd, answered: true, web: true, reused: true,
            budgetWarn: budget.warn,
            citations: reuse.citations.map((c) => ({ type: "web", label: c.title, url: c.url })),
          });
        }
      }
      // ② ★룸 위키 우선 + 웹 보강★ — 이 룸의 관련 위키를 컨텍스트로 넣는다(룸이 비면 text="" → 웹-전용 폴백).
      const room = await buildRoomContextForWeb(wikiScope, question);
      const wr = await answerWithWebSearch({ question, history: webHistory, provider: picked.provider, model: picked.model, roomContext: room.text || undefined });
      await prisma.message.create({
        data: { conversationId: conv.id, role: "assistant", content: wr.answer, webSourced: true },
      });
      await prisma.conversation.update({ where: { id: conv.id }, data: { title: conv.title ?? question.slice(0, 40) } });
      await recordUsage({ userId: user.id, scope: wikiScope, kind: "websearch", model: picked.model, inputTokens: wr.usage.inputTokens, outputTokens: wr.usage.outputTokens });
      // ③ ★웹 Q&A를 QueryLog에 저장★(webSourced — 재사용 캐시 전용, git 위키·검색·위키질의 미진입). 독립 질문·실답만.
      if (webHistory.length === 0 && wr.answer.trim()) {
        await recordWebQuery({ scope: wikiScope, userId: user.id, question, answerMd: wr.answer, citations: wr.citations, inputTokens: wr.usage.inputTokens, outputTokens: wr.usage.outputTokens });
      }
      return NextResponse.json({
        conversationId: conv.id,
        answer: wr.answer,
        answered: true,
        web: true,
        budgetWarn: budget.warn,
        usedModel: picked.model,
        usedProvider: picked.provider,
        citations: wr.citations.map((c) => ({ type: "web", label: c.title, url: c.url })),
      });
    }

    // ── 위키 경로 ── (ACL 강제지점2: loadPages가 wikiScope 페이지만 로드)
    const result = await answerQuery({ scope: wikiScope, question, userId: user.id, history: wikiHistory, model: picked.model, provider: picked.provider, think: picked.think, includeCommon: includeCommon === true });

    // 어시스턴트 메시지 기록 + 대화 touch
    await prisma.message.create({
      data: { conversationId: conv.id, role: "assistant", content: result.answerMd, queryLogId: result.queryId },
    });
    await prisma.conversation.update({ where: { id: conv.id }, data: { title: conv.title ?? question.slice(0, 40) } });

    // 출처 칩 라벨은 ★한국어 제목★(frontmatter title)으로 — 영문 파일명(slug) 대신. 위키 트리·인용과 동일 규칙.
    const citeTitles = await pageTitles(result.citedPaths);
    // 인용 근거 — 각 인용 페이지에서 질문과 가장 겹치는 문장(왜 인용됐는지). 로컬 계산.
    const citeSnippets: Record<string, string> = {};
    await Promise.all(result.citedPaths.map(async (p) => {
      try { citeSnippets[p] = bestSupportingSentence(await fs.readFile(wikiAbsPath(p), "utf8"), question); } catch { /* 페이지 없으면 생략 */ }
    }));
    // ★근거 신뢰도(A-1)★ — 인용 수 + 인용 페이지 최신성으로 강/보통/약(LLM 호출 0, 있는 데이터 재사용).
    //   인용 페이지의 가장 최근 갱신일(WikiDoc.updatedAt)로 '오래됨' 여부를 본다.
    let freshestUpdatedDays: number | null = null;
    if (result.citedPaths.length) {
      const docs = await prisma.wikiDoc.findMany({ where: { path: { in: result.citedPaths } }, select: { updatedAt: true } });
      if (docs.length) {
        const newest = Math.max(...docs.map((d) => d.updatedAt.getTime()));
        freshestUpdatedDays = Math.floor((Date.now() - newest) / 86_400_000);
      }
    }
    const evidence = evidenceLevel({ citedCount: result.citedPaths.length, freshestUpdatedDays });
    return NextResponse.json({
      conversationId: conv.id,
      answer: result.answerMd,
      answered: result.answered,
      budgetWarn: budget.warn, // 오늘 토큰 사용량이 한도의 80%↑ → 화면에 임박 경고
      evidence, // 근거 신뢰도 신호(A-1): { level: strong|medium|weak|none, drivers: [...] }
      // ★출처 범위 라벨(A-2)★ — cross-scope 답에서 '이 방/회사 공통/상위 방' 구분(표시 전용).
      citations: result.citedPaths.map((p) => ({ type: "wiki", label: citeTitles[p] || (p.split("/").pop()?.replace(/\.md$/, "") ?? p), path: p, snippet: citeSnippets[p] || undefined, scopeLabel: scopePathLabel(p, wikiScope) })),
      usedModel: result.usedModel,
      usedProvider: result.usedProvider, // 답변한 모델의 공급자(채팅 아바타 아이콘용)
      usage: result.usage, // ★모델·토큰 표시★ — 비공개 질의도 채팅에서 어떤 모델이 얼마 썼는지 보이게
      fallback: result.fallback, // 1순위 한도/오류로 백업 모델이 대신 답했으면 {fromModel, reason}
      reused: result.reused === true, // 최근 동일 질문의 답을 재사용(토큰 0)
      queryId: result.queryId, // 승격(룸 공용화)·기록용
      promotable: result.promotable === true, // 비공개 답 → 본인이 룸 공용으로 승격 가능
      suggestedQuestions: result.suggestedQuestions, // 눌러서 바로 질의할 추천 질문(버튼)
    });
  } catch (err) {
    return NextResponse.json({ error: String(err) }, { status: 500 });
  }
}

