{m.citations && m.citations.length > 0 && (() => {
  // A-2: 인용들이 ★서로 다른 범위★에 걸쳐 있을 때만 범위 배지를 보인다(같은 범위면 노이즈라 숨김).
  const showScope = new Set(m.citations.filter((c) => c.type === "wiki" && c.scopeLabel).map((c) => c.scopeLabel)).size > 1;
  return m.citations.some((c) => c.snippet) ? (
    // 근거 문장이 있으면 ‘칩 + 왜 인용됐는지’ 세로 목록으로.
