        {c.snippet && <span className="cite-snippet" title="이 문장이 답변 근거">“{c.snippet}”</span>}
      </div>
    ))}</div>
  ) : (
    <div className="citations-row">{m.citations.map((c) => <CitationChip key={c.id} c={c} onOpenWiki={onOpenWiki} showScope={showScope} />)}</div>
  );
})()}
