                      {p.summary && <span className="rev-past-summary">{p.summary}</span>}
                    </button>
                    <span className="rev-past-meta">{fmtWhen(p.decidedAt)}</span>
                  </div>
                  {/* 펼침: 검토 당시 사유·모순·변경(diff) — GET /api/review/[jobId](status 무관) 재사용 */}
                  {openDiff.has(p.jobId) && (
                    <div className="rev-past-detail">
                      {(diffData[p.jobId]?.reviewReason || p.reviewReason) && (
                        <div className="rev-reason"><IconInfoCircle size={13} style={{ verticalAlign: "-2px", marginRight: 4 }} />검토 사유: {diffData[p.jobId]?.reviewReason || p.reviewReason}</div>
                      )}
                      {diffData[p.jobId]?.contradictions && diffData[p.jobId]!.contradictions!.length > 0 && (
                        <div className="mat-banner err" style={{ display: "block", margin: "0 0 8px" }}>
                          <div style={{ fontWeight: 600, marginBottom: 4 }}><IconAlertTriangle size={14} style={{ verticalAlign: "-2px", marginRight: 4 }} />기존 위키와 모순이던 항목</div>
                          <ul style={{ margin: 0, paddingLeft: 18 }}>
                            {diffData[p.jobId]!.contradictions!.map((c, i) => <li key={i}><b>{c.subject}</b>: 기존 「{c.existing}」 ↔ 새 자료 「{c.incoming}」</li>)}
                          </ul>
                        </div>
                      )}
                      {diffBusy.has(p.jobId) && !diffData[p.jobId] ? <div className="rev-diff-loading">불러오는 중…</div>
                        : (diffData[p.jobId]?.edits ?? []).map((ed, i) => (
                          <div key={i} className="rev-diff-file">
                            <div className="rev-diff-head">
                              <b>{ed.op === "create" ? (ed.isNew ? "새 페이지" : "전체 교체") : "내용 추가"}</b>
                              <span className="rev-diff-path">{ed.path}</span>
                              <span className="rev-diff-stat">+{ed.diff.added}{ed.diff.removed ? ` −${ed.diff.removed}` : ""}</span>
                            </div>
                            <pre className="rev-diff-body">
                              {ed.diff.lines.map((l, k) => <div key={k} className={`diff-line ${l.type}`}>{`${l.type === "add" ? "+" : l.type === "del" ? "−" : " "} ${l.text}`}</div>)}
                              {ed.diff.truncated && <div className="diff-line ctx">… (이하 생략 — 변경이 너무 큼)</div>}
                            </pre>
                          </div>
                        ))}
                      {p.canReDecide && (
                        <div className="rev-past-actions">
                          {p.decision === "rejected"
                            ? <button className="modal-btn primary" disabled={busy === p.jobId} onClick={() => reDecide(p, "approve")}><IconCheck size={14} />{busy === p.jobId ? "처리 중…" : "다시 승인·적용"}</button>
                            : <button className="modal-btn ghost" disabled={busy === p.jobId} onClick={() => reDecide(p, "reject")}><IconArrowBackUp size={14} />{busy === p.jobId ? "처리 중…" : "승인 되돌리기 → 재검토"}</button>}
                        </div>
                      )}
                    </div>
                  )}
                </div>
              ))}
            </div>
          </>
        )}
    </>
  );
  // 모달 모드(onClose): 페이지 래퍼 없이 내용만(카드·X·백드롭은 AppShell이 제공).
  if (onClose) return <div className="set-wrap set-modal-wrap">{body}</div>;
  return (
    <div className="set-page"><div className="set-wrap">
      <a className="set-back" href="/"><IconArrowLeft size={15} />위키로 돌아가기</a>
      <h1 className="set-title"><IconChecklist size={20} style={{ verticalAlign: "-3px", marginRight: 8 }} />검토 콘솔</h1>
      {body}
    </div></div>
  );
}

