import { NextResponse } from "next/server";
import { getSessionUser } from "@/lib/auth/session";
import { prisma } from "@/lib/db";
import { roomContext } from "@/lib/projects";

// 룸 아카이브 — OWNER 전용. archivedAt 설정 시 allowedScopes에서 제외되어 사이드바에서 사라짐. docs/11 §3.
// (본문 위키는 보존; soft-delete. 복구/완전삭제는 후속.)
export const runtime = "nodejs";

export async function POST(req: Request, { params }: { params: Promise<{ slug: string }> }) {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "로그인이 필요합니다." }, { status: 401 });
  const { slug } = await params;

  const ctx = await roomContext(user.id, slug);
  if (!ctx) return NextResponse.json({ error: "룸을 찾을 수 없습니다." }, { status: 404 });
  if (ctx.role !== "OWNER") return NextResponse.json({ error: "권한이 없습니다 (OWNER 전용)." }, { status: 403 });

  await prisma.project.update({ where: { id: ctx.project.id }, data: { archivedAt: new Date() } });
  return NextResponse.json({ ok: true });
}

