import { NextResponse } from "next/server";
import { getSessionUser } from "@/lib/auth/session";
import { assertScopeAllowed, scopeWikiPrefix } from "@/lib/acl/scope";
import { prisma } from "@/lib/db";

// 내 비공개 질의 목록 — 계획 A5. 본인의 PRIVATE(아직 미승격) Q&A를 최신순으로. ACL: 접근 가능 scope만.
export const runtime = "nodejs";

export async function GET(req: Request) {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "로그인이 필요합니다." }, { status: 401 });
  const scope = new URL(req.url).searchParams.get("scope") ?? "";
  try {
    await assertScopeAllowed(user, scope);
  } catch {
    return NextResponse.json({ error: "접근 권한이 없는 scope입니다." }, { status: 403 });
  }
  const wikiScope = scopeWikiPrefix(scope);
  const rows = await prisma.queryLog.findMany({
    where: { userId: user.id, teamScope: wikiScope, visibility: "PRIVATE", webSourced: false },
    orderBy: { id: "desc" },
    take: 30,
    select: { id: true, question: true, answerMd: true, createdAt: true, filedPath: true, citedPaths: true, model: true, inputTokens: true, outputTokens: true },
  });
  return NextResponse.json({
    queries: rows.map((r) => {
      let cited = 0;
      try { cited = (JSON.parse(r.citedPaths || "[]") as unknown[]).length; } catch { /* */ }
      // ★모델·토큰★도 함께 — 저장된 내 질의에서도 '어떤 모델이 답했고 토큰 얼마' 표시(라이브 채팅·자료와 통일).
      return { id: r.id, question: r.question, answerMd: r.answerMd, createdAt: r.createdAt.toISOString(), promoted: Boolean(r.filedPath), citedCount: cited, model: r.model, inputTokens: r.inputTokens, outputTokens: r.outputTokens };
    }),
  });
}

