import { NextResponse } from "next/server";
import { getSessionUser } from "@/lib/auth/session";
import { allowedScopes, scopeWikiPrefix } from "@/lib/acl/scope";
import { prisma } from "@/lib/db";
import { fileQueryToWiki } from "@/lib/query";

// 질의 승격 — 비공개(PRIVATE) Q&A를 그 룸의 공용 위키(queries/*)로 올린다. 계획 A4.
// 권한: ★질의한 본인★(log.userId === user.id) + 그 scope 접근 가능. 관리자 승인 불필요. 멱등(이미 공용이면 그대로).
export const runtime = "nodejs";

export async function POST(req: Request, { params }: { params: Promise<{ id: string }> }) {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "로그인이 필요합니다." }, { status: 401 });
  const id = Number((await params).id);
  if (!Number.isInteger(id) || id <= 0) return NextResponse.json({ error: "잘못된 id입니다." }, { status: 400 });
  const { anonymous } = await req.json().catch(() => ({})); // 익명으로 올리기(표시만 숨김, userId는 감사 유지)

  const log = await prisma.queryLog.findUnique({ where: { id } });
  if (!log) return NextResponse.json({ error: "질의를 찾을 수 없습니다." }, { status: 404 });
  if (log.userId !== user.id) return NextResponse.json({ error: "본인 질의만 룸 공용으로 올릴 수 있습니다." }, { status: 403 });
  // 그 scope에 여전히 접근 가능한지(멤버십). teamScope는 위키 접두(common·project-*·personal/<id>).
  const allowed = new Set((await allowedScopes(user)).map((s) => scopeWikiPrefix(s.id)));
  if (!allowed.has(log.teamScope)) return NextResponse.json({ error: "접근 권한이 없는 scope입니다." }, { status: 403 });

  try {
    // 익명 선택을 ★파일링 전★에 기록 → fileQueryToWiki가 '익명 기여자'로 페이지를 쓴다(userId는 그대로 유지).
    if (typeof anonymous === "boolean") await prisma.queryLog.update({ where: { id }, data: { anonymous } });
    const r = await fileQueryToWiki(id); // 멱등: 이미 공용이면 commitSha 빈 값
    return NextResponse.json({ ok: true, filedPath: r.filedPath, already: !r.commitSha });
  } catch (err) {
    return NextResponse.json({ error: String(err) }, { status: 500 });
  }
}

