import { NextResponse } from "next/server";
import { getSessionUser } from "@/lib/auth/session";
import { deleteQuery, QueryDeleteError } from "@/lib/query";

// 내 질의 삭제 — 본인 Q&A를 영구 제거(재사용 캐시·self-grounding·파일링 페이지/검색/임베딩 전수). docs/07 §6.
export const runtime = "nodejs";

export async function DELETE(_req: Request, { params }: { params: Promise<{ id: string }> }) {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "로그인이 필요합니다." }, { status: 401 });
  const id = Number((await params).id);
  if (!Number.isInteger(id) || id <= 0) return NextResponse.json({ error: "잘못된 질의 id입니다." }, { status: 400 });
  try {
    const r = await deleteQuery(id, user.id);
    return NextResponse.json(r);
  } catch (e) {
    if (e instanceof QueryDeleteError) return NextResponse.json({ error: e.message }, { status: e.status });
    return NextResponse.json({ error: String(e) }, { status: 500 });
  }
}

