import { NextResponse } from "next/server";
import { getSessionUser } from "@/lib/auth/session";
import { prisma } from "@/lib/db";

// 답변 피드백(자정작용) — 사용자가 한 Q&A에 👍/👎. 👎는 인용 페이지를 관리자 검토 신호로.
//   사용자당 한 Q&A에 1표(바꾸면 upsert). queryLogId는 자기 채팅 답변에서 옴.
export const runtime = "nodejs";

const REASONS = new Set(["outdated", "wrong", "insufficient"]);

export async function POST(req: Request) {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "로그인이 필요합니다." }, { status: 401 });
  const { queryLogId, rating, reason } = await req.json().catch(() => ({}));
  if (!Number.isInteger(queryLogId) || (rating !== "up" && rating !== "down")) {
    return NextResponse.json({ error: "queryLogId·rating(up|down)이 필요합니다." }, { status: 400 });
  }
  const ql = await prisma.queryLog.findUnique({ where: { id: queryLogId }, select: { teamScope: true } });
  if (!ql) return NextResponse.json({ error: "해당 Q&A를 찾을 수 없습니다." }, { status: 404 });
  const r = rating === "down" && typeof reason === "string" && REASONS.has(reason) ? reason : null;
  await prisma.answerFeedback.upsert({
    where: { queryLogId_userId: { queryLogId, userId: user.id } },
    create: { queryLogId, userId: user.id, scope: ql.teamScope, rating, reason: r },
    update: { rating, reason: r },
  });
  return NextResponse.json({ ok: true });
}

