3	import { useEffect, useState } from "react";
4	import { IconMessageReport, IconRefresh, IconThumbUp, IconThumbDown, IconNotes } from "@tabler/icons-react";
5	
6	interface FbItem { id: number; rating: string; reason: string | null; scope: string; createdAt: string; question: string; citedPaths: string[]; filedPath: string | null }
7	interface TopPage { path: string; count: number }
8	const reasonKo: Record<string, string> = { outdated: "오래됨", wrong: "틀림", insufficient: "부족" };
9	const pageName = (p: string) => p.split("/").pop()?.replace(/\.md$/, "") ?? p;
10	const kst = (iso: string) => new Date(iso).toLocaleString("ko-KR", { timeZone: "Asia/Seoul", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit" });
11	
12	export default function FeedbackConsole(_props: { onClose?: () => void } = {}) {
13	  const [items, setItems] = useState<FbItem[]>([]);
14	  const [summary, setSummary] = useState({ up: 0, down: 0, total: 0 });
15	  const [topPages, setTopPages] = useState<TopPage[]>([]);
16	  const [loading, setLoading] = useState(true);
17	  const [err, setErr] = useState<string | null>(null);
18	  const [onlyDown, setOnlyDown] = useState(true);
19	
20	  async function load() {
21	    setLoading(true); setErr(null);
22	    try {
23	      const r = await fetch("/api/admin/feedback", { cache: "no-store" });
24	      const d = await r.json();
25	      if (!r.ok) throw new Error(d.error || "불러오기 실패");
26	      setItems(d.items || []); setSummary(d.summary || { up: 0, down: 0, total: 0 }); setTopPages(d.topPages || []);
27	    } catch (e) { setErr(e instanceof Error ? e.message : String(e)); }
28	    finally { setLoading(false); }
29	  }
30	  useEffect(() => { load(); }, []);
31	
32	  const shown = onlyDown ? items.filter((i) => i.rating === "down") : items;
33	
34	  return (
35	    <div className="set-page"><div className="set-wrap">
36	      <h1 className="set-title"><IconMessageReport size={20} style={{ verticalAlign: "-3px", marginRight: 8 }} />답변 피드백 (관리자)</h1>
37	      <p className="set-note" style={{ marginTop: -6 }}>
38	        사용자가 답변에 남긴 👍/👎입니다. <b>👎가 인용한 페이지</b>가 곧 <b>고칠 1순위</b> — 자주 부정평가된 페이지부터 검토·보강하세요.
39	      </p>
40	
41	      <div className="au-summary">
42	        <div className="au-sumcard"><span className="au-sumlabel">👍 도움됨</span><span className="au-sumval">{summary.up}</span></div>
43	        <div className="au-sumcard"><span className="au-sumlabel">👎 별로</span><span className="au-sumval">{summary.down}</span></div>
44	        <div className="au-sumcard"><span className="au-sumlabel">전체</span><span className="au-sumval">{summary.total}</span></div>
45	        <button className="au-refresh" onClick={load} disabled={loading} title="새로고침"><IconRefresh size={14} />{loading ? "불러오는 중…" : "새로고침"}</button>
46	      </div>
47	
48	      {topPages.length > 0 && (
49	        <div className="fbc-top">
50	          <div className="rev-section-head" style={{ marginBottom: 6 }}>👎 자주 받은 페이지 (고칠 1순위)</div>
