import { NextResponse } from "next/server";
import { getSessionUser } from "@/lib/auth/session";
import { prisma } from "@/lib/db";

// 관리자 전용: 최근 답변 피드백 + 요약. 👎(인용 페이지)를 보고 무엇을 고칠지 판단.
export const runtime = "nodejs";

export async function GET() {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "로그인이 필요합니다." }, { status: 401 });
  if (user.role !== "ADMIN") return NextResponse.json({ error: "관리자만 볼 수 있습니다." }, { status: 403 });

  const fb = await prisma.answerFeedback.findMany({ orderBy: { createdAt: "desc" }, take: 200 });
  const qids = [...new Set(fb.map((f) => f.queryLogId))];
  const qls = qids.length
    ? await prisma.queryLog.findMany({
        where: { id: { in: qids } },
        select: { id: true, question: true, citedPaths: true, teamScope: true, filedPath: true, model: true },
      })
    : [];
  const byId = new Map(qls.map((q) => [q.id, q]));

  const items = fb.map((f) => {
    const q = byId.get(f.queryLogId);
    let cited: string[] = [];
    try { cited = q?.citedPaths ? (JSON.parse(q.citedPaths) as string[]) : []; } catch { /* noop */ }
    return {
      id: f.id, rating: f.rating, reason: f.reason, scope: f.scope,
      createdAt: f.createdAt.toISOString(),
      question: q?.question ?? "(원본 질의 없음)",
      citedPaths: cited, filedPath: q?.filedPath ?? null,
    };
  });
  // 요약: 👍/👎 총계 + 👎 인용 페이지별 빈도(가장 자주 부정평가된 페이지 = 고칠 1순위).
  const up = fb.filter((f) => f.rating === "up").length;
  const down = fb.filter((f) => f.rating === "down").length;
  const pageHits = new Map<string, number>();
  for (const it of items) if (it.rating === "down") for (const p of it.citedPaths) pageHits.set(p, (pageHits.get(p) ?? 0) + 1);
  const topPages = [...pageHits.entries()].map(([path, count]) => ({ path, count })).sort((a, b) => b.count - a.count).slice(0, 20);

  return NextResponse.json({ items, summary: { up, down, total: fb.length }, topPages });
}

