// ★공용★ 룸(scope)별 그룹핑(순수) — 여러 룸이 섞이는 목록(검토 콘솔 '이전 검토'·답변 피드백 등)을
//   "같은 룸끼리 한 묶음(룸 배너 하나 아래)"으로 보이게 한다. 입력 순서를 보존 → 그룹 순서 = 각 룸이
//   처음 등장한 순서(목록이 최신순이면 '가장 최근 활동 룸'이 위). 디자인 단일화: 표시는 RoomBadge + .room-badge.
export interface RoomGroup<T> {
  scope: string;
  scopeName: string;
  items: T[];
}

export function groupByRoom<T>(
  items: readonly T[],
  getScope: (it: T) => string,
  getName: (it: T) => string,
): RoomGroup<T>[] {
  const groups: RoomGroup<T>[] = [];
  const byScope = new Map<string, RoomGroup<T>>();
  for (const it of items) {
    const scope = getScope(it);
    let g = byScope.get(scope);
    if (!g) {
      g = { scope, scopeName: getName(it), items: [] };
      byScope.set(scope, g);
      groups.push(g); // 첫 등장 순서로 그룹 순서 고정
    }
    g.items.push(it);
  }
  return groups;
}

