  const name = (x: Row) => x.name;

  it("같은 룸끼리 묶고, 그룹 순서=첫 등장 순서를 보존한다", () => {
    const rows = [r(1, "common", "회사 공통"), r(2, "project-a", "A룸"), r(3, "common", "회사 공통"), r(4, "project-a", "A룸")];
    const g = groupByRoom(rows, get, name);
    expect(g.map((x) => x.scope)).toEqual(["common", "project-a"]); // common이 먼저 등장
    expect(g[0].items.map((x) => x.id)).toEqual([1, 3]);
    expect(g[1].items.map((x) => x.id)).toEqual([2, 4]);
    expect(g[0].scopeName).toBe("회사 공통");
  });

  it("그룹 내 항목 순서는 입력 순서 유지", () => {
    const rows = [r(5, "p", "P"), r(3, "p", "P"), r(9, "p", "P")];
    expect(groupByRoom(rows, get, name)[0].items.map((x) => x.id)).toEqual([5, 3, 9]);
  });

  it("빈 입력 → 빈 그룹", () => {
    expect(groupByRoom([], get, name)).toEqual([]);
