"use client";
import { useCallback, useEffect, useState } from "react";
import { IconBell, IconX, IconTrash } from "@tabler/icons-react";
import { kstStamp } from "@/lib/time";
import RoomBadge from "./RoomBadge";

// 인앱 알림 종🔔 (A-4 토대) — 안읽음 배지 + 드로어. 저빈도라 ★폴링★(60초)으로 충분(SSE 없음).
// 드로어를 열면 안읽음을 모두 읽음 처리. 항목 클릭 시 linkPath로 이동(있으면). 정기 잡(오래됨·다이제스트)이 알림을 생성.
interface Notif { id: number; type: string; title: string; body?: string | null; linkPath?: string | null; teamScope?: string | null; scopeName?: string | null; readAt?: string | null; createdAt: string }

// onOpenReview: 검토 알림(linkPath=/review)은 ★페이지 이동 대신 검토 모달★로 연다(AppShell·채팅 마운트 유지).
export default function NotificationBell({ onOpenReview }: { onOpenReview?: () => void } = {}) {
  const [items, setItems] = useState<Notif[]>([]);
  const [unread, setUnread] = useState(0);
  const [open, setOpen] = useState(false);

  const load = useCallback(async () => {
    try {
      const r = await fetch("/api/notifications", { cache: "no-store" });
      if (r.ok) { const d = await r.json(); setItems(d.items || []); setUnread(d.unread || 0); }
    } catch { /* 네트워크 실패는 조용히 — 다음 폴링에서 복구 */ }
  }, []);

  useEffect(() => { void load(); const t = setInterval(() => void load(), 20_000); return () => clearInterval(t); }, [load]); // 20초 폴링(새 알림 지연 단축). 드로어 열면 즉시 갱신.

  const toggle = () => {
    setOpen((o) => {
      const next = !o;
      if (next && unread > 0) { // 열면 안읽음 모두 읽음 처리(낙관적 + 서버 반영)
        setUnread(0);
        setItems((p) => p.map((n) => (n.readAt ? n : { ...n, readAt: new Date().toISOString() })));
        void fetch("/api/notifications/read", { method: "POST", headers: { "content-type": "application/json" }, body: "{}" }).catch(() => {});
      }
      return next;
    });
  };

  // 개별 삭제 — 낙관적 제거(+안읽음 보정) 후 서버 반영. 실패해도 다음 폴링에서 복구.
  const delOne = (n: Notif) => {
    setItems((p) => p.filter((x) => x.id !== n.id));
    if (!n.readAt) setUnread((u) => Math.max(0, u - 1));
    void fetch(`/api/notifications/${n.id}`, { method: "DELETE" }).catch(() => {});
  };
  // 전체 지우기 — 낙관적 비움 후 서버 반영.
  const clearAll = () => {
    setItems([]); setUnread(0);
    void fetch("/api/notifications", { method: "DELETE" }).catch(() => {});
  };

  return (
    <div className="notif-wrap">
      <button className="notif-bell" onClick={toggle} title="알림" aria-label={`알림${unread > 0 ? ` (안읽음 ${unread})` : ""}`}>
        <IconBell size={15} />
        {unread > 0 && <span className="notif-badge">{unread > 99 ? "99+" : unread}</span>}
      </button>
      {open && (
        <>
          <div className="notif-backdrop" onClick={() => setOpen(false)} />
          <div className="notif-drawer" role="dialog" aria-label="알림">
            <div className="notif-head">
              <span>알림</span>
              <div className="notif-head-actions">
                {items.length > 0 && <button className="notif-clear" onClick={clearAll} title="알림 전체 지우기"><IconTrash size={13} />전체 지우기</button>}
                <button className="modal-x" onClick={() => setOpen(false)} aria-label="닫기"><IconX size={15} /></button>
              </div>
            </div>
            {items.length === 0 ? (
              <div className="notif-empty">새 알림이 없습니다.</div>
            ) : (
              <div className="notif-list">
                {items.map((n) => (
                  <div key={n.id} className={`notif-item${n.readAt ? "" : " unread"}`}>
                    <button className="notif-item-main"
                      onClick={() => {
                        setOpen(false);
                        // 검토 콘솔은 모달로(페이지 이동 X). 그 외 딥링크는 기존대로 이동.
                        if (n.linkPath && n.linkPath.startsWith("/review") && onOpenReview) onOpenReview();
                        else if (n.linkPath) window.location.assign(n.linkPath);
                      }}>
                      {/* ★어느 룸인지★ — 알림은 여러 룸이 섞이므로 룸 배지를 또렷이(원시 scope 대신 사람이 읽는 이름). */}
                      {n.scopeName && <div className="notif-item-room"><IconBuildingCommunity size={12} />{n.scopeName}</div>}
                      <div className="notif-item-title">{n.title}</div>
                      {n.body && <div className="notif-item-body">{n.body}</div>}
                      <div className="notif-item-time">{kstStamp(new Date(n.createdAt))} KST</div>
                    </button>
                    <button className="notif-item-del" onClick={() => delOne(n)} title="이 알림 지우기" aria-label="이 알림 지우기"><IconX size={14} /></button>
                  </div>
                ))}
              </div>
            )}
          </div>
        </>
      )}
    </div>
  );
}

