import { NextResponse } from "next/server";
import { getSessionUser } from "@/lib/auth/session";
import { assertScopeReadable, scopeWikiPrefix, scopePathLabel } from "@/lib/acl/scope";
import { prisma } from "@/lib/db";
import { pageTitles } from "@/lib/wiki/context";

// ★B: 대화 지속(다음 날·새 탭·다른 기기 이어가기)★ — 그 사용자×룸의 ★가장 최근 대화★ + 메시지 + 내 피드백을
//   화면 복원용으로 반환한다. sessionStorage(같은 탭)만으로는 못 살리던 것을 서버에서 다시 불러온다.
//   ACL: 읽기 가드(assertScopeReadable, 아카이브 룸 열람 일관) + ★본인 대화만★(userId). 피드백도 본인 것만.
export const runtime = "nodejs";

export async function GET(req: Request) {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "로그인이 필요합니다." }, { status: 401 });
  const scope = new URL(req.url).searchParams.get("scope") ?? "";
  try {
    await assertScopeReadable(user, scope);
  } catch {
    return NextResponse.json({ error: "접근 권한이 없는 scope입니다." }, { status: 403 });
  }
  const wikiScope = scopeWikiPrefix(scope);

  const conv = await prisma.conversation.findFirst({
    where: { userId: user.id, scope: wikiScope },
    orderBy: { updatedAt: "desc" },
    select: { id: true },
  });
  if (!conv) return NextResponse.json({ conversationId: null, messages: [] });

  const msgs = await prisma.message.findMany({
    where: { conversationId: conv.id },
    orderBy: { id: "asc" },
    take: 100, // 최근 대화 한 스레드. 매우 긴 대화는 앞쪽이 잘릴 수 있음(살짝만 — 멀티턴 맥락은 chat 라우트가 별도로 20개 사용).
    select: { id: true, role: true, content: true, webSourced: true, queryLogId: true, createdAt: true },
  });

  // 봇 메시지의 QueryLog(인용·공유 상태) + 내 피드백을 한 번에 묶는다.
  const qids = msgs.map((m) => m.queryLogId).filter((x): x is number => typeof x === "number");
  const qls = qids.length
    ? await prisma.queryLog.findMany({ where: { id: { in: qids } }, select: { id: true, citedPaths: true, visibility: true, filedPath: true } })
    : [];
  const qlById = new Map(qls.map((q) => [q.id, q]));
  const fbs = qids.length
    ? await prisma.answerFeedback.findMany({ where: { queryLogId: { in: qids }, userId: user.id }, select: { queryLogId: true, rating: true, reason: true } })
    : [];
  const fbByQid = new Map(fbs.map((f) => [f.queryLogId, f]));

  // 인용 칩 라벨 = 한국어 제목(파일명 slug 대신). 스니펫은 복원 시 생략(비용 — 라이브 답에만).
  const parsePaths = (s: string | null): string[] => { try { const j = JSON.parse(s || "[]"); return Array.isArray(j) ? j.filter((x) => typeof x === "string") : []; } catch { return []; } };
  const allPaths = [...new Set(qls.flatMap((q) => parsePaths(q.citedPaths)))];
  const titles = allPaths.length ? await pageTitles(allPaths) : {};

  const messages = msgs.map((m) => {
    const time = m.createdAt.toTimeString().slice(0, 5); // 라이브 now()와 동일 형식(HH:MM)
    if (m.role === "user") return { role: "user" as const, text: m.content, time, msgId: m.id };
    const q = m.queryLogId != null ? qlById.get(m.queryLogId) : undefined;
    const fb = m.queryLogId != null ? fbByQid.get(m.queryLogId) : undefined;
    const cited = m.webSourced ? [] : parsePaths(q?.citedPaths ?? null); // 웹 답은 위키 인용 복원 안 함
    return {
      role: "bot" as const,
      text: m.content,
      time,
      msgId: m.id,
      queryId: m.queryLogId ?? undefined,
      web: m.webSourced,
      citations: cited.map((p) => ({ type: "wiki" as const, label: titles[p] || (p.split("/").pop()?.replace(/\.md$/, "") ?? p), path: p, scopeLabel: scopePathLabel(p, wikiScope) })),
      promoted: !!q?.filedPath,
      promotable: q?.visibility === "PRIVATE" && !q?.filedPath,
      feedback: fb ? { rating: fb.rating, reason: fb.reason ?? undefined } : undefined,
    };
  });

  return NextResponse.json({ conversationId: conv.id, messages });
}

