// ★B: 서버에서 최근 대화 복원★ — sessionStorage(같은 탭)에 대화가 없을 때(새 탭·다음 날·다른 기기) 서버의
//   가장 최근 대화·피드백을 불러와 화면을 복원하고 convId를 이어 다음 질문이 같은 대화로 계속되게 한다.
const scopeRef = useRef(scope); scopeRef.current = scope;
const hydratedRef = useRef<Set<string>>(new Set());
const hydrateFromServer = useCallback(async (sc: string) => {
  if (hydratedRef.current.has(sc)) return;                              // 룸당 1회만 시도(중복 fetch 방지)
  if ((cacheRef.current[sc]?.messages?.length ?? 0) > 0) return;        // 이미 이 세션에 대화 있음 → 서버로 덮지 않음
  hydratedRef.current.add(sc);
  try {
    const r = await fetch(`/api/conversations?scope=${encodeURIComponent(sc)}`, { cache: "no-store" });
    if (!r.ok) return;
    const d = await r.json();
    if (scopeRef.current !== sc) return;                               // 그새 룸이 바뀌면 버림(레이스 가드)
    const srv: SrvMsg[] = Array.isArray(d.messages) ? d.messages : [];
    if (srv.length === 0) return;
    if ((cacheRef.current[sc]?.messages?.length ?? 0) > 0) return;     // 그새 대화 시작됐으면 덮지 않음
    const restored: Msg[] = srv.map((m) => ({
      id: typeof m.msgId === "number" ? m.msgId : Date.now(),
      role: m.role === "user" ? "user" : "bot",
      time: m.time || "",
      text: m.text || "",
      citations: Array.isArray(m.citations) ? m.citations.map((c, i) => ({ ...c, id: `rc${m.msgId}-${i}` })) : undefined,
      web: m.web === true,
      queryId: m.queryId,
      promotable: m.promotable === true,
      promoted: m.promoted === true,
    }));
    const fb: Record<number, { rating: string; reason?: string }> = {};
    for (const m of srv) if (m.feedback && typeof m.msgId === "number") fb[m.msgId] = m.feedback;
    const cid = typeof d.conversationId === "number" ? d.conversationId : null;
    setMessages(restored);
    setConvId(cid);
    if (Object.keys(fb).length) setFbByMsg((s) => ({ ...s, ...fb }));
    cacheRef.current[sc] = { messages: restored.slice(-100), convId: cid };
    persistCache();
  } catch { /* 네트워크 실패는 조용히 — 다음 진입에 재시도 가능하도록 플래그 유지(과한 재시도는 피함) */ }
  // eslint-disable-next-line react-hooks/exhaustive-deps
}, []);

