// ★A: 지난 질문 회상★ — "내가 전에 뭐 물었지?" 류 메타 의도 감지(순수). 위키 grounding 대신 본인 QueryLog를
//   되짚어 답하는 분기에 쓴다. 과트리거 방지: 자기참조(내/전에/지난…) + 질문/물어 동사의 ★조합★일 때만 true.
//   일반 위키 질문("휴가 규정 알려줘"·"가입 절차 질문 있어요")은 false여야 한다.
const RECALL_PATTERNS: RegExp[] = [
  // 한국어: 자기참조(내가/전에/지난/이전/예전/아까/방금) + (무엇/뭐/무슨/어떤) + 질문/물어
  /내가?\s*(전에|예전에|아까|방금|지난번?|이전에?)\s*(뭐|무엇|뭘|무슨|어떤)?\s*(질문|물어|물었|여쭤|여쭀)/,
  /(지난|이전|예전|최근)\s*에?\s*(내가?\s*)?(한\s*)?질문/,
  /내\s*질문(들)?\s*(이?\s*)?(뭐|뭐였|목록|기록|보여|알려|있었)/,
  /(뭐|무엇|뭘|무슨\s*질문)\s*(을)?\s*(물어봤|물어봤었|물었었|물었|질문했)(지|더라|었지|나요?|니|어|을까)?/,
  // 영어
  /what (did|have) i (ask|asked)/,
  /my (previous|past|last|recent) questions?/,
];

export function isRecallIntent(question: string): boolean {
  const s = (question || "").toLowerCase().replace(/\s+/g, " ").trim();
  if (!s || s.length > 80) return false; // 너무 길면 진짜 질문일 가능성 ↑ — 회상은 짧은 한 줄
  return RECALL_PATTERNS.some((re) => re.test(s));
}

