import { describe, it, expect } from "vitest";
import { isRecallIntent } from "../lib/recall";

describe("isRecallIntent", () => {
  it("회상 의도(내/지난/이전 + 질문)는 true", () => {
    for (const q of [
      "내가 전에 무슨 질문 했었지?",
      "내가 전에 뭐 물었지?",
      "전에 뭐 물어봤지",
      "지난 질문 뭐였지",
      "이전에 한 질문 보여줘",
      "내 질문 목록 알려줘",
      "what did I ask before?",
      "my previous questions",
    ]) expect(isRecallIntent(q), q).toBe(true);
  });

  it("일반 위키 질문은 false(과트리거 방지)", () => {
    for (const q of [
      "휴가 규정 알려줘",
      "가입 절차에 대해 질문 있어요",
      "결제 게이트웨이가 뭐야?",
      "회의록 요약해줘",
      "이 프로젝트 담당자가 누구야?",
      "질문이 있는데 환불 정책 알려줘",
    ]) expect(isRecallIntent(q), q).toBe(false);
  });

  it("빈 문자열·과도하게 긴 문장은 false", () => {
    expect(isRecallIntent("")).toBe(false);
    expect(isRecallIntent("내가 전에 질문 " + "가".repeat(90))).toBe(false);
  });
});

