import { NextResponse } from "next/server";
import { getSessionUser } from "@/lib/auth/session";
import { prisma } from "@/lib/db";

// 관리자 전용: 사용 분석 + 지식 공백 — query_log에서 '뭘 더 문서화할지'를 도출. 데이터 외부 전송 0.
//   ① 지식 공백: 인용(citedPaths)이 비어 답을 못 준 질문 = 위키가 못 답한 것 → 문서화 대상.
//   ② 인기 페이지: 가장 자주 인용된 페이지 = 가장 쓸모 있는 지식.
//   ③ 인기 질문: 자주 반복된 질문(정규화 그룹).
export const runtime = "nodejs";

const norm = (q: string) => q.trim().toLowerCase().replace(/\s+/g, " ");

export async function GET() {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "로그인이 필요합니다." }, { status: 401 });
  if (user.role !== "ADMIN") return NextResponse.json({ error: "관리자만 볼 수 있습니다." }, { status: 403 });

  // 최근 위키 질의(웹질의 제외) — 최대 2000건.
  const rows = await prisma.queryLog.findMany({
    where: { webSourced: false },
    orderBy: { createdAt: "desc" },
    take: 2000,
    select: { question: true, citedPaths: true, teamScope: true, createdAt: true },
  });
  const parse = (s: string): string[] => { try { return JSON.parse(s || "[]") as string[]; } catch { return []; } };

  // ① 지식 공백 — 인용 0(근거 없이 답했거나 '모른다'). 같은 질문은 1건으로(최근 시각).
  const gapSeen = new Set<string>();
  const gaps: { question: string; scope: string; createdAt: string }[] = [];
  for (const r of rows) {
    if (parse(r.citedPaths).length > 0) continue;
    const k = norm(r.question);
    if (!k || gapSeen.has(k)) continue;
    gapSeen.add(k);
    gaps.push({ question: r.question, scope: r.teamScope, createdAt: r.createdAt.toISOString() });
    if (gaps.length >= 50) break;
  }

  // ② 인기 페이지 — 인용 빈도.
  const pageCount = new Map<string, number>();
  for (const r of rows) for (const p of parse(r.citedPaths)) pageCount.set(p, (pageCount.get(p) ?? 0) + 1);
  const popularPages = [...pageCount.entries()].map(([path, count]) => ({ path, count })).sort((a, b) => b.count - a.count).slice(0, 20);

  // ③ 인기 질문 — 정규화 그룹 빈도(대표 표기는 최초 등장).
  const qCount = new Map<string, { question: string; count: number }>();
  for (const r of rows) { const k = norm(r.question); if (!k) continue; const e = qCount.get(k); if (e) e.count++; else qCount.set(k, { question: r.question, count: 1 }); }
  const topQuestions = [...qCount.values()].filter((q) => q.count >= 2).sort((a, b) => b.count - a.count).slice(0, 20);

  return NextResponse.json({
    total: rows.length,
    gaps, popularPages, topQuestions,
    gapCount: gapSeen.size,
  });
}

