import { IconBulb, IconRefresh, IconNotes, IconMessageQuestion, IconStarFilled } from "@tabler/icons-react";

interface Gap { question: string; scope: string; createdAt: string }
interface PageHit { path: string; count: number }
interface QHit { question: string; count: number }
const pageName = (p: string) => p.split("/").pop()?.replace(/\.md$/, "") ?? p;
const kst = (iso: string) => new Date(iso).toLocaleString("ko-KR", { timeZone: "Asia/Seoul", month: "2-digit", day: "2-digit" });

export default function InsightsConsole(_props: { onClose?: () => void } = {}) {
  const [gaps, setGaps] = useState<Gap[]>([]);
  const [popularPages, setPopularPages] = useState<PageHit[]>([]);
  const [topQuestions, setTopQuestions] = useState<QHit[]>([]);
  const [total, setTotal] = useState(0);
  const [gapCount, setGapCount] = useState(0);
  const [loading, setLoading] = useState(true);
  const [err, setErr] = useState<string | null>(null);

  async function load() {
    setLoading(true); setErr(null);
    try {
      const r = await fetch("/api/admin/insights", { cache: "no-store" });
      const d = await r.json();
      if (!r.ok) throw new Error(d.error || "불러오기 실패");
      setGaps(d.gaps || []); setPopularPages(d.popularPages || []); setTopQuestions(d.topQuestions || []);
      setTotal(d.total || 0); setGapCount(d.gapCount || 0);
    } catch (e) { setErr(e instanceof Error ? e.message : String(e)); }
    finally { setLoading(false); }
  }
  useEffect(() => { load(); }, []);

  return (
    <div className="set-page"><div className="set-wrap">
      <h1 className="set-title"><IconBulb size={20} style={{ verticalAlign: "-3px", marginRight: 8 }} />사용 분석 · 지식 공백 (관리자)</h1>
      <p className="set-note" style={{ marginTop: -6 }}>
        최근 질의(최대 2000건)에서 <b>위키를 어떻게 키울지</b>를 봅니다. <b>지식 공백</b>은 위키가 출처로 답하지 못한 질문 — <b>다음에 문서화할 1순위</b>입니다.
      </p>

      <div className="au-summary">
        <div className="au-sumcard"><span className="au-sumlabel">분석한 질의</span><span className="au-sumval">{total}</span></div>
        <div className="au-sumcard"><span className="au-sumlabel">지식 공백(미응답)</span><span className="au-sumval">{gapCount}</span></div>
        <button className="au-refresh" onClick={load} disabled={loading} title="새로고침"><IconRefresh size={14} />{loading ? "불러오는 중…" : "새로고침"}</button>
      </div>

      {err && <div className="mat-banner err">{err}</div>}

      <div className="rev-section-head" style={{ marginTop: 14 }}><IconMessageQuestion size={14} style={{ verticalAlign: "-2px", marginRight: 5 }} />지식 공백 — 위키가 출처로 답하지 못한 질문</div>
      {gaps.length === 0 ? <div className="ins-empty">공백이 없습니다(또는 데이터 부족).</div> : (
        <div className="ins-list">
          {gaps.map((g, i) => (
            <div key={i} className="ins-gap">
              <span className="ins-q">{g.question}</span>
              <span className="ins-meta">{g.scope} · {kst(g.createdAt)}</span>
            </div>
          ))}
        </div>
      )}

      <div className="ins-cols">
        <div className="ins-col">
          <div className="rev-section-head"><IconStarFilled size={13} style={{ verticalAlign: "-2px", marginRight: 5, color: "#f59e0b" }} />인기 페이지 (가장 자주 인용)</div>
          {popularPages.length === 0 ? <div className="ins-empty">아직 없음</div> : popularPages.map((p) => (
            <div key={p.path} className="ins-row" title={p.path}><IconNotes size={12} /><span className="ins-row-name">{pageName(p.path)}</span><b className="ins-row-n">×{p.count}</b></div>
          ))}
        </div>
        <div className="ins-col">
          <div className="rev-section-head"><IconMessageQuestion size={13} style={{ verticalAlign: "-2px", marginRight: 5 }} />인기 질문 (자주 반복)</div>
          {topQuestions.length === 0 ? <div className="ins-empty">반복 질문 없음</div> : topQuestions.map((q, i) => (
            <div key={i} className="ins-row" title={q.question}><span className="ins-row-name">{q.question}</span><b className="ins-row-n">×{q.count}</b></div>
          ))}
        </div>
      </div>
    </div></div>
  );
}

