431:.ins-list { display: flex; flex-direction: column; gap: 6px; margin-top: 8px; }
432:.ins-gap { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; border: 1px solid var(--color-border-secondary); border-left: 3px solid var(--color-text-warning); border-radius: var(--border-radius-md); padding: 8px 11px; }
