"use client";

import { useEffect, useState } from "react";
import { IconMessageReport, IconRefresh, IconThumbUp, IconThumbDown, IconNotes } from "@tabler/icons-react";
import RoomBadge from "@/components/wiki/RoomBadge";
import { groupByRoom } from "@/lib/rooms/groupByRoom";

interface FbItem { id: number; rating: string; reason: string | null; scope: string; scopeName: string; createdAt: string; question: string; answer: string; citedPaths: string[]; filedPath: string | null }
interface TopPage { path: string; count: number }
const reasonKo: Record<string, string> = { outdated: "오래됨", wrong: "틀림", insufficient: "부족" };
const pageName = (p: string) => p.split("/").pop()?.replace(/\.md$/, "") ?? p;
const kst = (iso: string) => new Date(iso).toLocaleString("ko-KR", { timeZone: "Asia/Seoul", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit" });

export default function FeedbackConsole(_props: { onClose?: () => void } = {}) {
  const [items, setItems] = useState<FbItem[]>([]);
  const [summary, setSummary] = useState({ up: 0, down: 0, total: 0 });
  const [topPages, setTopPages] = useState<TopPage[]>([]);
  const [loading, setLoading] = useState(true);
  const [err, setErr] = useState<string | null>(null);
  const [onlyDown, setOnlyDown] = useState(true);

  async function load() {
    setLoading(true); setErr(null);
    try {
      const r = await fetch("/api/admin/feedback", { cache: "no-store" });
      const d = await r.json();
      if (!r.ok) throw new Error(d.error || "불러오기 실패");
      setItems(d.items || []); setSummary(d.summary || { up: 0, down: 0, total: 0 }); setTopPages(d.topPages || []);
    } catch (e) { setErr(e instanceof Error ? e.message : String(e)); }
    finally { setLoading(false); }
  }
  useEffect(() => { load(); }, []);

  const shown = onlyDown ? items.filter((i) => i.rating === "down") : items;

  return (
    <div className="set-page"><div className="set-wrap">
      <h1 className="set-title"><IconMessageReport size={20} style={{ verticalAlign: "-3px", marginRight: 8 }} />답변 피드백 (관리자)</h1>
      <p className="set-note" style={{ marginTop: -6 }}>
        사용자가 답변에 남긴 👍/👎입니다. <b>👎가 인용한 페이지</b>가 곧 <b>고칠 1순위</b> — 자주 부정평가된 페이지부터 검토·보강하세요.
      </p>

      <div className="au-summary">
        <div className="au-sumcard"><span className="au-sumlabel">👍 도움됨</span><span className="au-sumval">{summary.up}</span></div>
        <div className="au-sumcard"><span className="au-sumlabel">👎 별로</span><span className="au-sumval">{summary.down}</span></div>
        <div className="au-sumcard"><span className="au-sumlabel">전체</span><span className="au-sumval">{summary.total}</span></div>
        <button className="au-refresh" onClick={load} disabled={loading} title="새로고침"><IconRefresh size={14} />{loading ? "불러오는 중…" : "새로고침"}</button>
      </div>

      {topPages.length > 0 && (
        <div className="fbc-top">
          <div className="rev-section-head" style={{ marginBottom: 6 }}>👎 자주 받은 페이지 (고칠 1순위)</div>
          {topPages.map((t) => (
            <span key={t.path} className="fbc-toppage" title={t.path}><IconNotes size={12} />{pageName(t.path)} <b>×{t.count}</b></span>
          ))}
        </div>
      )}

      <label className="web-toggle" style={{ margin: "12px 0 8px" }}>
        <input type="checkbox" role="switch" aria-checked={onlyDown} checked={onlyDown} onChange={(e) => setOnlyDown(e.target.checked)} />
        <span className="web-toggle-label">👎만 보기</span>
      </label>

      {err && <div className="mat-banner err">{err}</div>}
      {!err && !loading && shown.length === 0 && <div className="wt-empty">피드백이 없습니다.</div>}

      {/* ★룸별로 묶기★ — 검토 콘솔 '이전 검토'와 동일 패턴(공용 groupByRoom + RoomBadge 헤더). */}
      <div className="fbc-list">
        {groupByRoom(shown, (i) => i.scope, (i) => i.scopeName || i.scope).map((g) => (
          <div key={g.scope} className="fbc-group">
            <RoomBadge name={g.scopeName} count={g.items.length} />
            {g.items.map((it) => (
              <div key={it.id} className={`fbc-item${it.rating === "down" ? " down" : ""}`}>
                <div className="fbc-head">
                  <span className={`fbc-rate ${it.rating}`}>{it.rating === "up" ? <IconThumbUp size={13} /> : <IconThumbDown size={13} />}</span>
                  {/* 사유 — 있으면 라벨, 👎인데 미선택이면 표시(어느 사유인지 안 떴다는 피드백 반영) */}
                  {it.reason ? <span className="fbc-reason">{reasonKo[it.reason] ?? it.reason}</span>
                    : it.rating === "down" ? <span className="fbc-reason none">사유 미선택</span> : null}
                  <span className="fbc-time">{kst(it.createdAt)}</span>
                </div>
                <div className="fbc-q" title="질문">Q. {it.question}</div>
                {/* ★그 질의의 답변★ — 무엇이 부정평가됐는지 보고 판단(길면 줄임, hover로 전체). */}
                {it.answer && <div className="fbc-a" title={it.answer}>A. {it.answer}</div>}
                {it.citedPaths.length > 0 && (
                  <div className="fbc-cites">
                    {it.citedPaths.map((p) => <span key={p} className="fbc-cite" title={p}><IconNotes size={11} />{pageName(p)}</span>)}
                  </div>
                )}
              </div>
            ))}
          </div>
        ))}
      </div>
    </div></div>
  );
}

