11	// onOpenReview: 검토 알림(linkPath=/review)은 ★페이지 이동 대신 검토 모달★로 연다(AppShell·채팅 마운트 유지).
12	export default function NotificationBell({ onOpenReview }: { onOpenReview?: () => void } = {}) {
13	  const [items, setItems] = useState<Notif[]>([]);
14	  const [unread, setUnread] = useState(0);
15	  const [open, setOpen] = useState(false);
16	
17	  const load = useCallback(async () => {
18	    try {
19	      const r = await fetch("/api/notifications", { cache: "no-store" });
20	      if (r.ok) { const d = await r.json(); setItems(d.items || []); setUnread(d.unread || 0); }
21	    } catch { /* 네트워크 실패는 조용히 — 다음 폴링에서 복구 */ }
22	  }, []);
23	
24	  useEffect(() => { void load(); const t = setInterval(() => void load(), 20_000); return () => clearInterval(t); }, [load]); // 20초 폴링(새 알림 지연 단축). 드로어 열면 즉시 갱신.
25	
26	  const toggle = () => {
27	    setOpen((o) => {
28	      const next = !o;
29	      if (next && unread > 0) { // 열면 안읽음 모두 읽음 처리(낙관적 + 서버 반영)
30	        setUnread(0);
31	        setItems((p) => p.map((n) => (n.readAt ? n : { ...n, readAt: new Date().toISOString() })));
32	        void fetch("/api/notifications/read", { method: "POST", headers: { "content-type": "application/json" }, body: "{}" }).catch(() => {});
33	      }
34	      return next;
35	    });
36	  };
37	
38	  // 개별 삭제 — 낙관적 제거(+안읽음 보정) 후 서버 반영. 실패해도 다음 폴링에서 복구.
39	  const delOne = (n: Notif) => {
40	    setItems((p) => p.filter((x) => x.id !== n.id));
41	    if (!n.readAt) setUnread((u) => Math.max(0, u - 1));
42	    void fetch(`/api/notifications/${n.id}`, { method: "DELETE" }).catch(() => {});
43	  };
44	  // 전체 지우기 — 낙관적 비움 후 서버 반영.
45	  const clearAll = () => {
46	    setItems([]); setUnread(0);
47	    void fetch("/api/notifications", { method: "DELETE" }).catch(() => {});
48	  };
49	
50	  return (
51	    <div className="notif-wrap">
52	      <button className="notif-bell" onClick={toggle} title="알림" aria-label={`알림${unread > 0 ? ` (안읽음 ${unread})` : ""}`}>
53	        <IconBell size={15} />
54	        {unread > 0 && <span className="notif-badge">{unread > 99 ? "99+" : unread}</span>}
55	      </button>
56	      {open && (
57	        <>
58	          <div className="notif-backdrop" onClick={() => setOpen(false)} />
59	          <div className="notif-drawer" role="dialog" aria-label="알림">
60	            <div className="notif-head">
61	              <span>알림</span>
