async function submitFeedback(m: Msg, rating: "up" | "down", reason?: string) {
  if (!m.queryId) return;
  // 낙관적 + ★sessionStorage 영속화★ — 메시지는 캐시로 복원되는데 피드백 표(fbByMsg)는 안 돼 새로고침 시 👍/👎가
  //   초기화되던 버그 수정. 메시지 id(Date.now 기반)로 키가 복원 메시지와 매칭된다(서버에도 저장됨, 여긴 화면 표시 복원용).
  setFbByMsg((s) => {
    const next = { ...s, [m.id]: { rating, reason } };
    try { sessionStorage.setItem(SS_KEY_FB, JSON.stringify(next)); } catch { /* quota 등 무시 */ }
    return next;
  });
  try {
    await fetch("/api/feedback", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ queryLogId: m.queryId, rating, reason }) });
  } catch { /* 실패해도 UI는 유지(가벼운 신호) */ }
}

