// 답변 피드백 — ★토글★: 같은 걸 다시 누르면 취소. reason 인자 유무로 '투표 버튼(👍/👎)' vs '사유 칩'을 구분한다.
//   ① reason 없음 = 👍/👎 버튼: 이미 그 평가면 ★전체 취소(삭제)★, 아니면 그 평가로(사유는 초기화).
//   ② reason 있음 = 사유 칩(항상 👎): 이미 그 사유면 ★사유만 해제★(👎 유지), 아니면 그 사유로.
async function submitFeedback(m: Msg, rating: "up" | "down", reason?: string) {
  if (!m.queryId) return;
  const cur = fbByMsg[m.id];
  let next: { rating: string; reason?: string } | undefined;
  if (reason === undefined) {
    next = cur?.rating === rating ? undefined : { rating }; // 같은 평가 재클릭 → 취소
  } else {
    next = { rating: "down", reason: cur?.reason === reason ? undefined : reason }; // 같은 사유 재클릭 → 사유 해제
  }
  // 낙관적 + ★sessionStorage 영속화★(새로고침 시 👍/👎 유지). 취소면 키 삭제.
  setFbByMsg((s) => {
    const n = { ...s };
    if (next) n[m.id] = next; else delete n[m.id];
    try { sessionStorage.setItem(SS_KEY_FB, JSON.stringify(n)); } catch { /* quota 등 무시 */ }
    return n;
  });
  try {
    // rating: null → 서버에서 그 피드백 삭제(취소). 그 외엔 upsert.
    await fetch("/api/feedback", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ queryLogId: m.queryId, rating: next ? next.rating : null, reason: next?.reason }) });
  } catch { /* 실패해도 UI는 유지(가벼운 신호) */ }
}

