// 서빙 모델 tier별 프롬프트: strong=HEAVY 편집셋(상호링크·index 유지), weak=SIMPLE(콘텐츠만·코드가 경로).
const build = (ctx: { tier: "strong" | "weak"; provider?: string }): BuiltPrompt => {
  if (ctx.tier === "strong" && heavyCtx) {
    const hasParent = heavyCtx.parentPages.length > 0;
    return {
      // 증강 모드(원본이 이미 topic으로 보존됨)면 ★원본 보존+그래프 추가★ 프롬프트, 아니면 일반 정리 프롬프트.
      system: input.augment && input.preservePath
        ? buildAugmentSystem(heavyCtx.brain, scope, input.preservePath, ctx.provider, ingestModel, hasParent)
        : buildSystem(heavyCtx.brain, scope, ctx.provider, ingestModel, hasParent, input.meeting),
      userText: buildUser({ scope, title: input.title, sha, text, index: heavyCtx.index, pages: heavyCtx.pages, parentPages: heavyCtx.parentPages, nativeAttachment, embeddedCount: input.assets?.length ?? 0 }),
      toolName: "submit_edit_set",
      toolDescription: "위키에 적용할 편집셋(JSON). 워커가 파일에 적용하고 git 커밋한다.",
      schema: EDIT_SET_SCHEMA,
      // strong(Gemini/Claude)은 출력 여유가 커 큰 .md 편집셋도 한 번에(잘림 방지). 공급자 최대 출력 사용(Gemini=65K).
      maxTokens: ingestMaxTokens(ctx.provider),
    };
  }
  return {
    system: SIMPLE_SYSTEM,
    userText: simpleUserText(input.title, text),
    toolName: "submit_note",
    toolDescription: "정리한 노트(JSON).",
    schema: SIMPLE_SCHEMA,
    maxTokens: Number(process.env.INGEST_MAX_TOKENS || 4096),
  };
};

const r = await callStructured<EditSet | SimpleNote>({
  model: ingestModel,
  provider: ingestProvider,
  think: ingestThink,
  images: allImages.length ? allImages : undefined,
  documents: input.documents,
  fallbacks,
  build,
  signal: input.signal,
});
const usage = r.usage;
const servedModel = r.model;
const fallbackInfo = r.fallback;

