export type IngestReco = { model: string; provider: string; label: string; reason: string };

// ★동기 코어★ — 미리 구한 disabled/explicitOn/fallback로 자료 형식·크기 기반 추천(소스별 추천을 DB 추가호출 없이 반복 호출).
export function pickIngestModel(signals: { chars?: number; type?: string; transcribed?: boolean }, ctx: { disabled: Set<string>; explicitOn: Set<string>; fallback: IngestReco }): IngestReco {
  const t = signals.type?.toUpperCase();
  const { disabled, explicitOn } = ctx;
  const xfer = (provider: string) => (provider === "codex" || provider === "openai" ? "OpenAI" : "Anthropic"); // reason 전송 경고

  // ★음성·영상 전사문 → Groq(무료·미학습)을 분석 기본으로★. 전사문은 텍스트라 Groq로 충분하고,
  //   외부 학습(Gemini)·유료(Claude)를 자동으로 쓰지 않는다. Groq 꺼졌으면 아래 일반 로직(보통 Gemini).
  if (signals.transcribed) {
    const g = groqIngestModel(disabled);
    if (g) return { ...g, reason: "음성을 텍스트로 변환한 자료라 무료·미학습 Groq을 분석 모델로 자동 선택했습니다(외부 학습 Gemini·유료 Claude를 자동으로 쓰지 않음). 원하면 직접 바꾸세요." };
  }

  // PDF: 원본 PDF를 직접 읽는 Gemini/Claude를 우선(표·수치 보존). 둘 다 없으면 아래 일반 로직으로.
  if (t && NATIVE_DOC_TYPES.has(t)) {
    const gm = geminiDefaultModel();
    if (geminiEnabled() && !disabled.has(gm)) {
      return { model: gm, provider: "gemini", label: `Gemini · ${gm}`,
        reason: "표·레이아웃이 있는 PDF라 원본을 ★직접 읽는★ Gemini를 자동 추천했습니다 — 표·수치 손실을 줄입니다. (codex는 PDF 원본을 못 읽어 표가 뭉개집니다.)\n⚠ 자료가 외부(Google)로 전송됩니다 — 민감 자료는 다른 모델로 바꾸세요." };
    }
    if (anthropicEnabled() && !disabled.has("claude-sonnet-4-6")) {
      return { model: "claude-sonnet-4-6", provider: "anthropic", label: "Claude Sonnet 4.6",
        reason: "표·레이아웃이 있는 PDF라 원본을 ★직접 읽는★ Claude를 자동 추천했습니다 — 표·수치 손실을 줄입니다. (Claude API 결제분 사용.)" };
    }
  }

  // 표 데이터(엑셀·CSV) → 행·열 구조화에 강한 ★추론 모델★(claude-cli 우선, 배포 codex). 없으면 아래 기본.
  if (t && TABULAR_TYPES.has(t)) {
    const r = bestReasoning(explicitOn, disabled);
    if (r) return { ...r, reason: `엑셀·CSV 같은 ★표 데이터★라 행·열 구조화에 강한 추론 모델(${r.label})을 자동 추천했습니다.\n⚠ 자료가 ${xfer(r.provider)}로 전송됩니다 — 민감 자료는 다른 모델로 바꾸세요.` };
  }

  // 큰 텍스트·문서 → 개체·개념 ★정밀 추출★을 위해 추론 모델(claude-cli 우선, 배포 codex). 없으면 아래 기본.
  //   (Gemini Flash는 빠르지만 큰 글에서 개체·개념 추출이 약해 그래프가 잘 안 늘어남.)
  if ((signals.chars ?? 0) > HEAVY_CHARS) {
    const r = bestReasoning(explicitOn, disabled);
    if (r) return { ...r, reason: `자료가 커서 개체·개념을 ★정밀 추출★하는 추론 모델(${r.label})을 자동 추천했습니다 — 무료 모델보다 그래프(개체·개념)가 잘 늘어납니다.\n⚠ 자료가 ${xfer(r.provider)}로 전송됩니다 — 민감 자료는 다른 모델로 바꾸세요.` };
  }

  // 그 외(짧은 텍스트·문서) → 기본(보통 Gemini: 빠름·무료).
  return ctx.fallback;
}

// 비동기 래퍼 — disabled/explicitOn/fallback를 구해 동기 코어에 위임(기존 호출부 동작 불변).
export async function recommendIngestModel(signals: { chars?: number; type?: string; transcribed?: boolean }): Promise<IngestReco> {
  const [disabled, explicitOn, fallback] = await Promise.all([disabledModelIds(), enabledModelIds(), ingestModelChoice()]);
  return pickIngestModel(signals, { disabled, explicitOn, fallback });
}

