toolUseResult.originalFile:
// 회의 지식화(B-1 M1). 전사문(STT)을 ★회의 모드★로 분석할 때 인제스트 system 프롬프트에 더하는 지침.
// ★새 추출기·새 쓰기 경로 없음★ — strong tier 인제스트 프롬프트에 이 블록만 덧붙여, 전사문에서
// 회의 구조(요약·결정사항·액션아이템·안건요약)를 구조적으로 뽑아 topics 페이지로 정리하게 한다.
// 담당 귀속은 화자 라벨이 있을 때만 '후보'로, 실명 확정은 사람이. 상세: docs/PLAN-meeting-intelligence.md §4·§5.

// 회의 페이지 본문에서 ★화자 라벨★(화자1·화자2…)을 중복 없이 추출(번호순). M2 매핑 패널용.
export function detectSpeakers(content: string): string[] {
  const set = new Set(content.match(/화자\d+(?!\d)/g) ?? []);
  return [...set].sort((a, b) => Number(a.slice(2)) - Number(b.slice(2)));
}

// 화자 라벨 → 실제 이름 치환(M2 사람 확정). mapping 예: {화자1:'박철수'}. 빈 이름은 건너뛴다.
// '화자1'이 '화자10'의 일부로 잘못 치환되지 않게 뒤에 숫자가 오면 제외((?!\d)). 단일 라이터로 커밋된다.
export function applySpeakerMap(content: string, mapping: Record<string, string>): string {
  let out = content;
  for (const [label, name] of Object.entries(mapping)) {
    const nm = (name || "").trim();
    if (!nm || !/^화자\d+$/.test(label)) continue;
    out = out.replace(new RegExp(label + "(?!\\d)", "g"), nm);
  }
  return out;
}

