    "  ## 결정사항 — 결정된 것을 목록으로. 각 항목 끝에 화자 라벨(있으면)·타임스탬프를 단다. 예: `- 배포 파이프라인 정리 — 화자2 · [12:30]`.",
    "  ## 액션아이템 — 체크박스 목록: `- [ ] 작업 — 담당: …(없으면 생략) · 기한: …(없으면 '미지정') · [타임스탬프]`.",
    "  ## 안건별 요약 — 안건/주제별 핵심.",
    "  ## 전체 대화 — ★전사문 전체를 빠짐없이 그대로★ 옮긴다(요약·생략·축약 금지). 화자 라벨·타임스탬프·(기침) 같은 비음성 표시도 그대로 둔다. 너무 길어 다 못 담으면 가능한 만큼 담고 needs_human=true로 표시한다(원문 전체는 '추출본'에도 완전히 보존됨).",
    "- ★verbatim 우선·추측 금지★: 작업·결정은 전사문 표현을 살려 옮기고, ★없는 기한·담당을 지어내지 않는다★(없으면 '미지정'/생략).",
    "- ★담당 귀속★: 화자 라벨이 전사문에 ★있을 때만★ 담당 후보로 적되 '(후보)'로 표기한다. ★화자 구분이 없으면(평문) 담당을 비운다★(오귀속 금지). 음성만으로 실명을 단정하지 말 것 — 실명 확정은 사람이 한다.",
    "- 타임스탬프가 전사문에 있으면 각 항목에 붙여 ★역추적★ 가능하게 한다(없으면 생략).",
    "- 회의에 등장한 핵심 개체·개념은 일반 규칙대로 entities/concepts로도 정리·상호링크한다.",
  ].join("\n");
}

// ── 회의 지식화 고도화 — 본문 ## 액션아이템 섹션을 ★구조화 항목★으로 파싱(순수·테스트). action_item 메타DB 적재용. ──
//   형식(meetingPromptGuidance): `- [ ] 작업 — 담당: …(생략 가능) · 기한: …('미지정' 포함) · [타임스탬프]`
export interface ParsedActionItem { task: string; owner: string | null; deadline: string | null; timestamp: string | null; done: boolean }

export function parseActionItems(md: string): ParsedActionItem[] {
  const start = (md || "").search(/^##\s*액션아이템\s*$/m);
  if (start < 0) return [];
  let body = md.slice(start).replace(/^##.*\n?/, ""); // 헤딩 줄 제거
  const nextH = body.search(/^##\s/m);
  if (nextH >= 0) body = body.slice(0, nextH); // 다음 섹션 전까지
  const items: ParsedActionItem[] = [];
  for (const line of body.split("\n")) {
    const mm = line.match(/^\s*[-*]\s*\[([ xX])\]\s*(.+?)\s*$/);
    if (!mm) continue;
    const done = /x/i.test(mm[1]);
    let rest = mm[2];
    let timestamp: string | null = null;
    const ts = rest.match(/\[([^\]]+)\]\s*$/); // 끝의 [타임스탬프]
    if (ts) { timestamp = ts[1].trim(); rest = rest.slice(0, ts.index).replace(/[·•\-\s]+$/, ""); }
    const ow = rest.match(/담당\s*:\s*([^·•]+?)(?:\s*[·•]|$)/); const owner = ow ? ow[1].trim() : null;
    const dl = rest.match(/기한\s*:\s*([^·•]+?)(?:\s*[·•]|$)/); const deadline = dl ? dl[1].trim() : null;
    // task = 담당/기한/타임스탬프 앞의 본문(— 또는 · 구분 우선).
    let task = rest.split(/\s+[—–]\s+/)[0];
    task = task.replace(/\s*[·•]\s*(담당|기한)\s*:.*/, "").replace(/[·•\-\s]+$/, "").trim();
    if (task) items.push({ task, owner, deadline, timestamp, done });
  }
  return items;
}

